CREATE OR REPLACE FUNCTION app_private.accept_invitation(p_invitation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  actor_email text;
  invitation public.invitations%rowtype;
  membership_id uuid;
  correlation uuid := gen_random_uuid();
begin
  if actor is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  select lower(u.email) into actor_email
  from auth.users as u
  where u.id = actor and u.email_confirmed_at is not null;

  if actor_email is null then
    raise exception using errcode = '42501', message = 'verified_email_required';
  end if;

  select i.* into invitation
  from public.invitations as i
  where i.id = p_invitation_id
  for update;

  if not found
    or invitation.email <> actor_email
    or invitation.status not in ('pending', 'accepted') then
    raise exception using errcode = '42501', message = 'invitation_not_available';
  end if;

  if invitation.status = 'accepted' then
    if invitation.accepted_by is distinct from actor then
      raise exception using errcode = '42501', message = 'invitation_already_used';
    end if;
    if invitation.kind = 'internal' then
      select am.id into membership_id
      from public.agency_memberships as am
      where am.user_id = actor and am.agency_id = invitation.agency_id;
    else
      select cm.id into membership_id
      from public.client_memberships as cm
      where cm.user_id = actor and cm.organization_id = invitation.organization_id;
    end if;
    return membership_id;
  end if;

  if invitation.expires_at <= now() then
    raise exception using errcode = '22023', message = 'invitation_expired';
  end if;

  if invitation.kind = 'internal' then
    insert into public.agency_memberships (
      user_id, agency_id, role_key, department_id, status, classification
    ) values (
      actor, invitation.agency_id, invitation.agency_role_key,
      invitation.department_id, 'active', invitation.classification
    )
    on conflict (user_id, agency_id) do update
      set role_key = excluded.role_key,
          department_id = excluded.department_id,
          status = 'active',
          classification = excluded.classification,
          archived_at = null
      where public.agency_memberships.status in ('invited', 'archived')
    returning id into membership_id;
  else
    insert into public.client_memberships (
      user_id, organization_id, role_key, status, invited_by
    ) values (
      actor, invitation.organization_id, invitation.client_role_key,
      'active', invitation.invited_by
    )
    on conflict (user_id, organization_id) do update
      set role_key = excluded.role_key,
          status = 'active',
          invited_by = excluded.invited_by,
          archived_at = null
      where public.client_memberships.status in ('invited', 'archived')
    returning id into membership_id;
  end if;

  if membership_id is null then
    raise exception using errcode = '23505', message = 'active_membership_exists';
  end if;

  update public.invitations
  set status = 'accepted', accepted_by = actor, accepted_at = now()
  where id = invitation.id;

  perform app_private.emit_event(
    'auth.invitation.accepted', actor, 'invitation', invitation.id,
    invitation.agency_id, invitation.organization_id, correlation, null,
    jsonb_build_object('kind', invitation.kind, 'membership_id', membership_id)
  );

  return membership_id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.add_project_member(p_project_id uuid, p_user_id uuid, p_member_type text, p_responsibility text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target_project public.projects%rowtype;
  target_agency uuid;
  target_organization uuid;
  created_id uuid;
  correlation uuid := gen_random_uuid();
begin
  select de.resource_id into created_id
  from public.domain_events as de
  where de.actor_id = actor
    and de.event_type = 'project.member.added'
    and de.idempotency_key = p_idempotency_key;
  if created_id is not null then return created_id; end if;

  select * into target_project from public.projects where id = p_project_id for update;
  select o.agency_id, o.id into target_agency, target_organization
  from public.brands as b
  join public.organizations as o on o.id = b.organization_id
  where b.id = target_project.brand_id;

  if actor is null or p_user_id = actor
    or target_project.id is null or target_project.archived_at is not null
    or not app_private.can_manage_project_members(target_project.id) then
    raise exception using errcode = '42501', message = 'project_member_manage_forbidden';
  end if;

  if p_member_type = 'internal' then
    if p_responsibility not in ('lead', 'member') or not exists (
      select 1 from public.agency_memberships as am
      where am.user_id = p_user_id and am.agency_id = target_agency
        and am.status = 'active'
    ) then
      raise exception using errcode = '22023', message = 'invalid_internal_project_member';
    end if;
  elsif p_member_type = 'client' then
    if p_responsibility <> 'client_member' or not exists (
      select 1 from public.client_memberships as cm
      where cm.user_id = p_user_id and cm.organization_id = target_organization
        and cm.status = 'active'
    ) then
      raise exception using errcode = '22023', message = 'invalid_client_project_member';
    end if;
  else
    raise exception using errcode = '22023', message = 'invalid_project_member_type';
  end if;

  insert into public.project_memberships (
    project_id, user_id, member_type, responsibility, status,
    created_by, revoked_at
  ) values (
    target_project.id, p_user_id, p_member_type, p_responsibility,
    'active', actor, null
  )
  on conflict (project_id, user_id) do update
  set member_type = excluded.member_type,
      responsibility = excluded.responsibility,
      status = 'active',
      revoked_at = null,
      created_by = actor
  returning id into created_id;

  perform app_private.emit_event(
    'project.member.added', actor, 'project_membership', created_id,
    target_agency, target_organization, correlation, p_idempotency_key,
    jsonb_build_object('project_id', target_project.id, 'user_id', p_user_id,
      'member_type', p_member_type, 'responsibility', p_responsibility)
  );
  return created_id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.apply_notification_preferences()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_preferences public.notification_preferences%rowtype;
begin
 select * into v_preferences from public.notification_preferences where user_id=new.recipient_id;
 if (new.kind='message_received' and v_preferences.messages is false)
  or (new.kind='approval_pending' and v_preferences.approvals is false)
  or (new.kind in ('deliverable_published','client_approved','client_changes_requested')
   and v_preferences.deliverable_updates is false) then return null; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION app_private.archive_client_membership(p_membership_id uuid, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  membership public.client_memberships%rowtype;
  membership_agency uuid;
  correlation uuid := gen_random_uuid();
begin
  if actor is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  select cm.* into membership
  from public.client_memberships as cm
  where cm.id = p_membership_id
  for update;

  if found then
    select o.agency_id into membership_agency
    from public.organizations as o
    where o.id = membership.organization_id;
  end if;

  if not found
    or membership.user_id = actor
    or not public.has_capability(
      'client_user.revoke', membership_agency, membership.organization_id
    ) then
    raise exception using errcode = '42501', message = 'client_membership_archive_forbidden';
  end if;

  if membership.status <> 'archived' then
    update public.client_memberships
    set status = 'archived', archived_at = now()
    where id = membership.id;

    perform app_private.emit_event(
      'client.member.revoked', actor, 'client_membership', membership.id,
      membership_agency, membership.organization_id, correlation,
      p_idempotency_key, '{}'::jsonb
    );
  end if;

  return membership.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.archive_crm_resource(p_resource_type text, p_resource_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid()); organization_id uuid; agency_id uuid;
  required_capability text; correlation uuid := gen_random_uuid();
begin
  if p_resource_type = 'organization' then
    select o.id, o.agency_id into organization_id, agency_id from public.organizations o where o.id = p_resource_id for update;
    required_capability := 'organization.manage';
  elsif p_resource_type = 'brand' then
    select b.organization_id, o.agency_id into organization_id, agency_id from public.brands b join public.organizations o on o.id=b.organization_id where b.id=p_resource_id for update of b;
    required_capability := 'brand.manage';
  elsif p_resource_type = 'contact' then
    select c.organization_id, o.agency_id into organization_id, agency_id from public.contacts c join public.organizations o on o.id=c.organization_id where c.id=p_resource_id for update of c;
    required_capability := 'contact.manage';
  elsif p_resource_type = 'opportunity' then
    select op.organization_id, o.agency_id into organization_id, agency_id from public.opportunities op join public.organizations o on o.id=op.organization_id where op.id=p_resource_id for update of op;
    required_capability := 'opportunity.manage';
  else raise exception using errcode='22023', message='unsupported_archive_resource'; end if;
  if organization_id is null or actor is null or not public.has_capability(required_capability, agency_id, organization_id) then
    raise exception using errcode='42501', message='crm_archive_forbidden';
  end if;
  if p_resource_type = 'organization' then update public.organizations set lifecycle='archived', archived_at=now() where id=p_resource_id;
  elsif p_resource_type = 'brand' then update public.brands set status='archived', archived_at=now() where id=p_resource_id;
  elsif p_resource_type = 'contact' then update public.contacts set status='archived', archived_at=now() where id=p_resource_id;
  else update public.opportunities set status='archived', archived_at=now() where id=p_resource_id; end if;
  perform app_private.emit_event(p_resource_type || '.archived', actor, p_resource_type, p_resource_id,
    agency_id, organization_id, correlation, null, '{}'::jsonb);
  return p_resource_id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.archive_project(p_project_id uuid, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.projects%rowtype;
  target_agency uuid;
  target_organization uuid;
  correlation uuid := gen_random_uuid();
begin
  if exists (
    select 1 from public.domain_events as de
    where de.actor_id = actor and de.event_type = 'project.archived'
      and de.idempotency_key = p_idempotency_key
  ) then return p_project_id; end if;

  select * into target from public.projects where id = p_project_id for update;
  if target.id is null
    or not app_private.project_permission(target.id, 'project.manage') then
    raise exception using errcode = '42501', message = 'project_archive_forbidden';
  end if;
  if target.status = 'archived' then return target.id; end if;

  select o.agency_id, o.id into target_agency, target_organization
  from public.brands as b
  join public.organizations as o on o.id = b.organization_id
  where b.id = target.brand_id;

  update public.projects
  set status = 'archived', archived_at = now()
  where id = target.id;

  perform app_private.emit_event(
    'project.archived', actor, 'project', target.id, target_agency,
    target_organization, correlation, p_idempotency_key, '{}'::jsonb
  );
  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.archive_work_item(p_work_item_id uuid, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform 1 from public.work_items wi where wi.id=p_work_item_id for update;
  if exists(select 1 from public.editorial_items ei where ei.work_item_id=p_work_item_id
    and ei.planning_state in ('planned','available')) then
    raise exception using errcode='22023', message='archive_editorial_first';
  end if;
  return app_private.archive_work_item_core(p_work_item_id,p_idempotency_key);
end;
$function$

CREATE OR REPLACE FUNCTION app_private.archive_work_item_core(p_work_item_id uuid, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.work_items%rowtype;
  correlation uuid := gen_random_uuid();
begin
  if exists (
    select 1 from public.domain_events as de
    where de.actor_id = actor and de.event_type = 'work.archived'
      and de.resource_id = p_work_item_id
      and de.idempotency_key = p_idempotency_key
  ) then return p_work_item_id; end if;
  select * into target from public.work_items where id = p_work_item_id for update;
  if target.id is null or not app_private.project_permission(target.project_id, 'work.archive') then
    raise exception using errcode = '42501', message = 'work_archive_forbidden';
  end if;
  if target.archived_at is not null then return target.id; end if;
  update public.work_items set archived_at = now() where id = target.id;
  perform app_private.record_work_event(
    target.id, 'work.archived', actor, correlation, p_idempotency_key,
    jsonb_build_object('status', target.status)
  );
  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.assign_work_item(p_work_item_id uuid, p_assignee_ids uuid[], p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.editorial_items%rowtype; actor uuid := (select auth.uid());
  assigned uuid; correlation uuid := gen_random_uuid(); rejected record;
begin
  perform 1 from public.work_items wi where wi.id=p_work_item_id for update;
  select * into target from public.editorial_items ei where ei.work_item_id=p_work_item_id for update;
  if target.id is not null and target.planning_state in ('planned','available')
    and cardinality(coalesce(p_assignee_ids,'{}'::uuid[])) <> 1 then
    raise exception using errcode='22023', message='editorial_requires_one_assignee';
  end if;
  assigned := app_private.assign_work_item_core(p_work_item_id,p_assignee_ids,p_idempotency_key);
  if target.id is not null and target.planning_state in ('planned','available') then
    for rejected in update public.work_applications set status='rejected',resolved_at=now(),resolved_by=actor
      where editorial_item_id=target.id and status='pending' returning id loop
      perform app_private.record_editorial_event(target.project_id,'editorial.application.rejected','work_application',rejected.id,actor,correlation,null,
        jsonb_build_object('editorial_item_id',target.id,'reason','manual_assignment'));
    end loop;
    update public.editorial_items set planning_state='assigned' where id=target.id;
    perform app_private.record_editorial_event(target.project_id,'editorial.item.assigned','editorial_item',target.id,actor,correlation,null,
      jsonb_build_object('work_item_id',p_work_item_id,'reason','manual_assignment'));
  end if;
  return assigned;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.assign_work_item_core(p_work_item_id uuid, p_assignee_ids uuid[], p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.work_items%rowtype;
  old_assignees uuid[];
  new_assignees uuid[];
  assignee uuid;
  event_name text;
  correlation uuid := gen_random_uuid();
begin
  if exists (
    select 1 from public.domain_events as de
    where de.actor_id = actor
      and de.event_type in ('work.assigned', 'work.reassigned')
      and de.resource_id = p_work_item_id
      and de.idempotency_key = p_idempotency_key
  ) then return p_work_item_id; end if;

  select * into target from public.work_items where id = p_work_item_id for update;
  if target.id is null or target.archived_at is not null
    or not app_private.project_permission(target.project_id, 'work.assign') then
    raise exception using errcode = '42501', message = 'work_assign_forbidden';
  end if;

  select coalesce(array_agg(distinct candidate order by candidate), '{}'::uuid[])
  into new_assignees
  from unnest(coalesce(p_assignee_ids, '{}'::uuid[])) as candidate;
  if cardinality(new_assignees) = 0 then
    raise exception using errcode = '22023', message = 'work_requires_assignee';
  end if;

  foreach assignee in array new_assignees loop
    if not exists (
      select 1 from public.project_memberships as pm
      where pm.project_id = target.project_id and pm.user_id = assignee
        and pm.member_type = 'internal' and pm.status = 'active'
    ) then
      raise exception using errcode = '22023', message = 'assignee_not_active_project_member';
    end if;
  end loop;

  select coalesce(array_agg(wia.user_id order by wia.user_id), '{}'::uuid[])
  into old_assignees
  from public.work_item_assignees as wia
  where wia.work_item_id = target.id and wia.revoked_at is null;

  if old_assignees = new_assignees then return target.id; end if;

  update public.work_item_assignees
  set revoked_at = now()
  where work_item_id = target.id and revoked_at is null
    and not (user_id = any(new_assignees));

  foreach assignee in array new_assignees loop
    insert into public.work_item_assignees (
      work_item_id, user_id, assigned_by, assigned_at, revoked_at
    ) values (target.id, assignee, actor, now(), null)
    on conflict (work_item_id, user_id) do update
    set assigned_by = actor, assigned_at = now(), revoked_at = null;
  end loop;

  event_name := case when cardinality(old_assignees) = 0
    then 'work.assigned' else 'work.reassigned' end;
  perform app_private.record_work_event(
    target.id, event_name, actor, correlation, p_idempotency_key,
    jsonb_build_object('from', to_jsonb(old_assignees), 'to', to_jsonb(new_assignees))
  );
  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.can_manage_channel(p_channel uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_c public.channels%rowtype; v_agency uuid; v_role text;
begin
 select * into v_c from public.channels where id=p_channel and archived_at is null;
 if v_c.id is null or auth.uid() is null then return false; end if;
 select agency_id into v_agency from public.organizations where id=v_c.organization_id;
 select role_key into v_role from public.agency_memberships
 where user_id=auth.uid() and agency_id=v_agency and status='active';
 if v_role is null then return false; end if;
 if v_c.kind='project' then
  return app_private.project_permission(v_c.project_id,'channel.manage_members')
   and app_private.can_manage_project_members(v_c.project_id);
 end if;
 return v_role='agency_director' or exists(
  select 1 from public.capability_grants g where g.user_id=auth.uid()
   and g.organization_id=v_c.organization_id and g.capability_key='channel.manage_members'
   and g.revoked_at is null and (g.expires_at is null or g.expires_at>now()));
end; $function$

CREATE OR REPLACE FUNCTION app_private.can_read_work_item(p_work_item_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target_project uuid;
  actor_role text;
begin
  select wi.project_id into target_project
  from public.work_items as wi
  where wi.id = p_work_item_id;

  if target_project is null
    or not app_private.project_permission(target_project, 'work.view') then
    return false;
  end if;

  select am.role_key into actor_role
  from public.projects as p
  join public.brands as b on b.id = p.brand_id
  join public.organizations as o on o.id = b.organization_id
  join public.agency_memberships as am on am.agency_id = o.agency_id
  where p.id = target_project
    and am.user_id = actor
    and am.status = 'active';

  if actor_role in ('agency_director', 'project_manager') then return true; end if;

  return actor_role = 'contributor' and exists (
    select 1
    from public.work_item_assignees as wia
    where wia.work_item_id = p_work_item_id
      and wia.user_id = actor
      and wia.revoked_at is null
  );
end;
$function$

CREATE OR REPLACE FUNCTION app_private.change_opportunity_stage(p_opportunity_id uuid, p_stage_key text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid()); target public.opportunities%rowtype;
  target_org public.organizations%rowtype; next_outcome text; next_status text;
  correlation uuid := gen_random_uuid(); event_name text;
begin
  if exists (select 1 from public.domain_events de where de.actor_id = actor
    and de.event_type in ('opportunity.stage_changed','opportunity.won','opportunity.lost')
    and de.idempotency_key = p_idempotency_key) then return p_opportunity_id; end if;
  select * into target from public.opportunities where id = p_opportunity_id for update;
  select * into target_org from public.organizations where id = target.organization_id;
  if target.id is null or actor is null or target.status = 'archived'
    or not public.has_capability('opportunity.manage', target_org.agency_id, target_org.id) then
    raise exception using errcode = '42501', message = 'opportunity_manage_forbidden';
  end if;
  select ps.outcome into next_outcome from public.pipeline_stages ps
  where ps.key = p_stage_key and ps.is_active;
  if next_outcome is null then raise exception using errcode = '22023', message = 'invalid_pipeline_stage'; end if;
  next_status := case next_outcome when 'won' then 'won' when 'lost' then 'lost' else 'open' end;
  update public.opportunities set stage_key = p_stage_key, status = next_status,
    closed_at = case when next_status in ('won','lost') then now() else null end
  where id = target.id;
  insert into public.crm_activities (organization_id, opportunity_id, activity_type, summary, details, created_by, is_system_generated)
  values (target.organization_id, target.id, 'stage_change', 'Opportunity stage changed',
    target.stage_key || ' → ' || p_stage_key, actor, true);
  event_name := case next_status when 'won' then 'opportunity.won' when 'lost' then 'opportunity.lost' else 'opportunity.stage_changed' end;
  perform app_private.emit_event(event_name, actor, 'opportunity', target.id,
    target_org.agency_id, target_org.id, correlation, p_idempotency_key,
    jsonb_build_object('from', target.stage_key, 'to', p_stage_key));
  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.create_brand(p_organization_id uuid, p_name text, p_timezone text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid()); target public.organizations%rowtype;
  created_id uuid; correlation uuid := gen_random_uuid();
begin
  select de.resource_id into created_id from public.domain_events de
  where de.actor_id = actor and de.event_type = 'brand.created'
    and de.idempotency_key = p_idempotency_key;
