CREATE OR REPLACE FUNCTION app_private.create_invitation(p_kind text, p_email text, p_agency_role_key text, p_department_key text, p_classification text, p_organization_id uuid, p_client_role_key text, p_idempotency_key uuid)
 RETURNS TABLE(invitation_id uuid, normalized_email text, invitation_kind text, is_replay boolean, was_dispatched boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  actor_agency uuid;
  target_department uuid;
  target_department_category text;
  normalized text := lower(btrim(p_email));
  existing public.invitations%rowtype;
  expired_id uuid;
  created_id uuid;
  correlation uuid := gen_random_uuid();
  event_type text;
begin
  if actor is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  if char_length(normalized) not between 3 and 320 or position('@' in normalized) <= 1 then
    raise exception using errcode = '22023', message = 'invalid_invitation_email';
  end if;

  select i.* into existing
  from public.invitations as i
  where i.invited_by = actor and i.idempotency_key = p_idempotency_key;

  if found then
    return query select existing.id, existing.email, existing.kind, true,
      existing.email_sent_at is not null;
    return;
  end if;

  if p_kind = 'internal' then
    select am.agency_id into actor_agency
    from public.agency_memberships as am
    where am.user_id = actor
      and am.status = 'active'
      and public.has_capability('agency.member.invite', am.agency_id, null)
    order by am.created_at
    limit 1;

    if actor_agency is null then
      raise exception using errcode = '42501', message = 'internal_invitation_forbidden';
    end if;

    if p_organization_id is not null or p_client_role_key is not null then
      raise exception using errcode = '22023', message = 'invalid_internal_invitation';
    end if;

    if not exists (
      select 1 from public.roles as r
      where r.key = p_agency_role_key and r.context = 'agency'
    ) then
      raise exception using errcode = '22023', message = 'invalid_agency_role';
    end if;

    select d.id, d.category into target_department, target_department_category
    from public.departments as d
    where d.agency_id = actor_agency and d.key = p_department_key and d.is_active;

    if target_department is null
      or (p_agency_role_key = 'agency_director' and target_department_category <> 'direction')
      or (p_agency_role_key <> 'agency_director' and target_department_category <> 'operations')
      or p_classification not in ('founder', 'employee', 'external_collaborator', 'contractor') then
      raise exception using errcode = '22023', message = 'invalid_agency_role_department';
    end if;

    update public.invitations
    set status = 'expired'
    where kind = 'internal'
      and agency_id = actor_agency
      and email = normalized
      and status = 'pending'
      and expires_at <= now()
    returning id into expired_id;

    if expired_id is not null then
      perform app_private.emit_event(
        'auth.invitation.expired', actor, 'invitation', expired_id,
        actor_agency, null, correlation, null,
        jsonb_build_object('kind', 'internal')
      );
      correlation := gen_random_uuid();
    end if;

    select i.* into existing
    from public.invitations as i
    where i.kind = 'internal'
      and i.agency_id = actor_agency
      and i.email = normalized
      and i.status = 'pending';

    if found then
      if existing.agency_role_key is distinct from p_agency_role_key
        or existing.department_id is distinct from target_department
        or existing.classification is distinct from p_classification then
        raise exception using errcode = '23505', message = 'pending_invitation_conflict';
      end if;
      return query select existing.id, existing.email, existing.kind, true,
        existing.email_sent_at is not null;
      return;
    end if;

    insert into public.invitations (
      kind, email, agency_id, agency_role_key, department_id,
      classification, invited_by, idempotency_key
    ) values (
      'internal', normalized, actor_agency, p_agency_role_key, target_department,
      p_classification, actor, p_idempotency_key
    ) returning id into created_id;
    event_type := 'agency.member.invited';
  elsif p_kind = 'client' then
    select o.agency_id into actor_agency
    from public.organizations as o
    where o.id = p_organization_id
      and o.archived_at is null
      and public.has_capability('client_user.invite', o.agency_id, o.id);

    if actor_agency is null then
      raise exception using errcode = '42501', message = 'client_invitation_forbidden';
    end if;

    if p_agency_role_key is not null or p_department_key is not null or p_classification is not null then
      raise exception using errcode = '22023', message = 'invalid_client_invitation';
    end if;

    if not exists (
      select 1 from public.roles as r
      where r.key = p_client_role_key and r.context = 'client'
    ) then
      raise exception using errcode = '22023', message = 'invalid_client_role';
    end if;

    update public.invitations
    set status = 'expired'
    where kind = 'client'
      and organization_id = p_organization_id
      and email = normalized
      and status = 'pending'
      and expires_at <= now()
    returning id into expired_id;

    if expired_id is not null then
      perform app_private.emit_event(
        'auth.invitation.expired', actor, 'invitation', expired_id,
        actor_agency, p_organization_id, correlation, null,
        jsonb_build_object('kind', 'client')
      );
      correlation := gen_random_uuid();
    end if;

    select i.* into existing
    from public.invitations as i
    where i.kind = 'client'
      and i.organization_id = p_organization_id
      and i.email = normalized
      and i.status = 'pending';

    if found then
      if existing.client_role_key is distinct from p_client_role_key then
        raise exception using errcode = '23505', message = 'pending_invitation_conflict';
      end if;
      return query select existing.id, existing.email, existing.kind, true,
        existing.email_sent_at is not null;
      return;
    end if;

    insert into public.invitations (
      kind, email, agency_id, organization_id, client_role_key,
      invited_by, idempotency_key
    ) values (
      'client', normalized, actor_agency, p_organization_id, p_client_role_key,
      actor, p_idempotency_key
    ) returning id into created_id;
    event_type := 'client.member.invited';
  else
    raise exception using errcode = '22023', message = 'invalid_invitation_kind';
  end if;

  perform app_private.emit_event(
    event_type, actor, 'invitation', created_id, actor_agency, p_organization_id,
    correlation, p_idempotency_key, jsonb_build_object('kind', p_kind)
  );

  return query select created_id, normalized, p_kind, false, false;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.create_milestone(p_project_id uuid, p_name text, p_description text, p_due_date date, p_sort_order integer, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  created_id uuid;
  correlation uuid := gen_random_uuid();
begin
  select de.resource_id into created_id
  from public.domain_events as de
  where de.actor_id = actor and de.event_type = 'milestone.created'
    and de.idempotency_key = p_idempotency_key;
  if created_id is not null then return created_id; end if;

  if actor is null or not app_private.project_permission(p_project_id, 'milestone.manage')
    or exists (select 1 from public.projects where id = p_project_id and archived_at is not null) then
    raise exception using errcode = '42501', message = 'milestone_create_forbidden';
  end if;
  if char_length(btrim(p_name)) not between 1 and 160 or p_sort_order < 0 then
    raise exception using errcode = '22023', message = 'invalid_milestone_input';
  end if;

  insert into public.milestones (
    project_id, name, description, due_date, sort_order, created_by
  ) values (
    p_project_id, btrim(p_name), nullif(btrim(p_description), ''),
    p_due_date, p_sort_order, actor
  ) returning id into created_id;

  perform app_private.emit_event(
    'milestone.created', actor, 'milestone', created_id,
    (select o.agency_id from public.projects p join public.brands b on b.id=p.brand_id join public.organizations o on o.id=b.organization_id where p.id=p_project_id),
    (select b.organization_id from public.projects p join public.brands b on b.id=p.brand_id where p.id=p_project_id),
    correlation, p_idempotency_key, jsonb_build_object('project_id', p_project_id)
  );
  return created_id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.create_opportunity(p_organization_id uuid, p_brand_id uuid, p_name text, p_stage_key text, p_estimated_value numeric, p_currency text, p_owner_id uuid, p_expected_close_date date, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid()); target public.organizations%rowtype;
  created_id uuid; correlation uuid := gen_random_uuid(); stage_outcome text;
begin
  select de.resource_id into created_id from public.domain_events de
  where de.actor_id = actor and de.event_type = 'opportunity.created'
    and de.idempotency_key = p_idempotency_key;
  if created_id is not null then return created_id; end if;
  select * into target from public.organizations where id = p_organization_id;
  if target.id is null or actor is null
    or not public.has_capability('opportunity.create', target.agency_id, target.id) then
    raise exception using errcode = '42501', message = 'opportunity_create_forbidden';
  end if;
  select ps.outcome into stage_outcome from public.pipeline_stages ps
  where ps.key = p_stage_key and ps.is_active;
  if stage_outcome is distinct from 'open' then
    raise exception using errcode = '22023', message = 'initial_stage_must_be_open';
  end if;
  if not exists (
    select 1 from public.agency_memberships am
    where am.user_id = p_owner_id and am.agency_id = target.agency_id and am.status = 'active'
  ) then raise exception using errcode = '22023', message = 'invalid_opportunity_owner'; end if;
  insert into public.opportunities (
    organization_id, brand_id, name, stage_key, estimated_value,
    currency, owner_id, expected_close_date
  ) values (
    target.id, p_brand_id, btrim(p_name), p_stage_key, p_estimated_value,
    upper(btrim(p_currency)), p_owner_id, p_expected_close_date
  ) returning id into created_id;
  insert into public.crm_activities (organization_id, opportunity_id, activity_type, summary, created_by, is_system_generated)
  values (target.id, created_id, 'opportunity_created', 'Opportunity created: ' || btrim(p_name), actor, true);
  perform app_private.emit_event('opportunity.created', actor, 'opportunity', created_id,
    target.agency_id, target.id, correlation, p_idempotency_key,
    jsonb_build_object('stage', p_stage_key));
  return created_id;
end;
$function$

