CREATE OR REPLACE FUNCTION app_private.create_project(p_brand_id uuid, p_name text, p_description text, p_status text, p_start_date date, p_target_end_date date, p_timezone text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target_brand public.brands%rowtype;
  target_organization public.organizations%rowtype;
  target_agency uuid;
  actor_role text;
  created_id uuid;
  membership_id uuid;
  correlation uuid := gen_random_uuid();
begin
  select de.resource_id into created_id
  from public.domain_events as de
  where de.actor_id = actor
    and de.event_type = 'project.created'
    and de.idempotency_key = p_idempotency_key;
  if created_id is not null then return created_id; end if;

  select * into target_brand from public.brands where id = p_brand_id;
  select * into target_organization
  from public.organizations where id = target_brand.organization_id;
  target_agency := target_organization.agency_id;

  if actor is null
    or target_brand.id is null
    or target_brand.status <> 'active'
    or target_organization.lifecycle <> 'active_client'
    or not public.has_capability('project.create', target_agency, target_organization.id) then
    raise exception using errcode = '42501', message = 'project_create_forbidden';
  end if;

  if p_status not in ('planning', 'active', 'on_hold')
    or char_length(btrim(p_name)) not between 1 and 200
    or (p_start_date is not null and p_target_end_date is not null and p_target_end_date < p_start_date) then
    raise exception using errcode = '22023', message = 'invalid_project_input';
  end if;

  insert into public.projects (
    brand_id, name, description, status, start_date, target_end_date,
    timezone, created_by
  ) values (
    target_brand.id, btrim(p_name), nullif(btrim(p_description), ''), p_status,
    p_start_date, p_target_end_date, nullif(btrim(p_timezone), ''), actor
  ) returning id into created_id;

  select am.role_key into actor_role
  from public.agency_memberships as am
  where am.user_id = actor and am.agency_id = target_agency and am.status = 'active';

  if actor_role <> 'agency_director' then
    insert into public.project_memberships (
      project_id, user_id, member_type, responsibility, created_by
    ) values (created_id, actor, 'internal', 'lead', actor)
    returning id into membership_id;
  end if;

  perform app_private.emit_event(
    'project.created', actor, 'project', created_id, target_agency,
    target_organization.id, correlation, p_idempotency_key,
    jsonb_build_object('brand_id', target_brand.id, 'initial_membership_id', membership_id)
  );

  return created_id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.create_work_item(p_project_id uuid, p_title text, p_description text, p_priority text, p_due_local timestamp without time zone, p_milestone_id uuid, p_assignee_ids uuid[], p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  created_id uuid;
  assignee uuid;
  correlation uuid := gen_random_uuid();
  normalized_assignees uuid[];
begin
  select de.resource_id into created_id
  from public.domain_events as de
  where de.actor_id = actor and de.event_type = 'work.created'
    and de.idempotency_key = p_idempotency_key;
  if created_id is not null then return created_id; end if;

  if actor is null or not app_private.project_permission(p_project_id, 'work.create')
    or exists (select 1 from public.projects where id = p_project_id and archived_at is not null) then
    raise exception using errcode = '42501', message = 'work_create_forbidden';
  end if;
  if char_length(btrim(p_title)) not between 1 and 240
    or p_priority not in ('low', 'normal', 'high', 'urgent') then
    raise exception using errcode = '22023', message = 'invalid_work_item_input';
  end if;
  if p_milestone_id is not null and not exists (
    select 1 from public.milestones as m
    where m.id = p_milestone_id and m.project_id = p_project_id
      and m.archived_at is null
  ) then
    raise exception using errcode = '22023', message = 'invalid_work_item_milestone';
  end if;

  select coalesce(array_agg(distinct candidate order by candidate), '{}'::uuid[])
  into normalized_assignees
  from unnest(coalesce(p_assignee_ids, '{}'::uuid[])) as candidate;

  foreach assignee in array normalized_assignees loop
    if not exists (
      select 1 from public.project_memberships as pm
      where pm.project_id = p_project_id and pm.user_id = assignee
        and pm.member_type = 'internal' and pm.status = 'active'
    ) then
      raise exception using errcode = '22023', message = 'assignee_not_active_project_member';
    end if;
  end loop;

  insert into public.work_items (
    project_id, milestone_id, title, description, priority,
    due_at, created_by
  ) values (
    p_project_id, p_milestone_id, btrim(p_title),
    nullif(btrim(p_description), ''), p_priority,
    case when p_due_local is null then null
      else p_due_local at time zone 'America/Mexico_City' end,
    actor
  ) returning id into created_id;

  foreach assignee in array normalized_assignees loop
    insert into public.work_item_assignees (
      work_item_id, user_id, assigned_by
    ) values (created_id, assignee, actor);
  end loop;

  perform app_private.record_work_event(
    created_id, 'work.created', actor, correlation, p_idempotency_key,
    jsonb_build_object('project_id', p_project_id, 'priority', p_priority)
  );
  if cardinality(normalized_assignees) > 0 then
    perform app_private.record_work_event(
      created_id, 'work.assigned', actor, correlation, null,
      jsonb_build_object('from', jsonb_build_array(), 'to', to_jsonb(normalized_assignees))
    );
  end if;
  return created_id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.create_work_item_comment(p_work_item_id uuid, p_body text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.work_items%rowtype;
  created_id uuid;
  created_event uuid;
  target_agency uuid;
  target_organization uuid;
  correlation uuid := gen_random_uuid();
begin
  select de.resource_id into created_id
  from public.domain_events as de
  where de.actor_id = actor and de.event_type = 'work.comment.created'
    and de.idempotency_key = p_idempotency_key;
  if created_id is not null then return created_id; end if;

  select * into target from public.work_items where id = p_work_item_id;
  if target.id is null or target.archived_at is not null
    or not app_private.can_read_work_item(target.id)
    or not app_private.project_permission(target.project_id, 'work.comment.create') then
    raise exception using errcode = '42501', message = 'work_comment_forbidden';
  end if;
  if char_length(btrim(p_body)) not between 1 and 8000 then
    raise exception using errcode = '22023', message = 'invalid_work_comment';
  end if;

  insert into public.work_item_comments (work_item_id, author_id, body)
  values (target.id, actor, btrim(p_body)) returning id into created_id;

  select o.agency_id, o.id into target_agency, target_organization
  from public.projects as p
  join public.brands as b on b.id = p.brand_id
  join public.organizations as o on o.id = b.organization_id
  where p.id = target.project_id;

  created_event := app_private.emit_event(
    'work.comment.created', actor, 'work_item_comment', created_id,
    target_agency, target_organization, correlation, p_idempotency_key,
    jsonb_build_object('work_item_id', target.id)
  );
  insert into public.work_item_events (
    work_item_id, domain_event_id, event_type, actor_id, payload
  ) values (
    target.id, created_event, 'work.comment.created', actor,
    jsonb_build_object('comment_id', created_id)
  );
  return created_id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.dashboard_crm_summary(p_max_items integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  result jsonb;
begin
  if not app_private.is_internal_actor()
    or not (
      exists (
        select 1 from public.my_capabilities() as capability
        where capability.capability_key in ('opportunity.view', 'organization.view')
      )
    ) then
    raise exception using errcode = '42501', message = 'dashboard_crm_forbidden';
  end if;
  if p_max_items not between 1 and 6 then
    raise exception using errcode = '22023', message = 'invalid_dashboard_summary_limit';
  end if;

  with authorized_organizations as materialized (
    select o.id, o.name, o.lifecycle, o.created_at
    from public.organizations as o
    where public.has_capability('organization.view', o.agency_id, o.id)
  ), authorized_opportunities as materialized (
    select op.id, op.name, op.organization_id, op.stage_key, op.status,
      op.estimated_value, op.currency, op.expected_close_date,
      o.name as organization_name
    from public.opportunities as op
    join public.organizations as o on o.id = op.organization_id
    where op.archived_at is null
      and public.has_capability('opportunity.view', o.agency_id, o.id)
  )
  select jsonb_build_object(
    'opportunities', jsonb_build_object(
      'openCount', (select count(*) from authorized_opportunities where status = 'open'),
      'items', (
        select coalesce(jsonb_agg(to_jsonb(opportunity_item)), '[]'::jsonb)
        from (
          select id as "opportunityId", name, organization_id as "organizationId",
            organization_name as "organizationName", stage_key as "stageKey",
            estimated_value as "estimatedValue", currency,
            expected_close_date as "expectedCloseDate"
          from authorized_opportunities where status = 'open'
          order by expected_close_date nulls last, name, id
          limit p_max_items
        ) as opportunity_item
      )
    ),
    'organizations', jsonb_build_object(
      'totalCount', (select count(*) from authorized_organizations),
      'activeClientCount', (
        select count(*) from authorized_organizations where lifecycle = 'active_client'
      ),
      'items', (
        select coalesce(jsonb_agg(to_jsonb(organization_item)), '[]'::jsonb)
        from (
          select id as "organizationId", name, lifecycle
          from authorized_organizations
          order by created_at desc, id desc
          limit p_max_items
        ) as organization_item
      )
    )
  ) into result;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.dashboard_operational_summary(p_max_items integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  result jsonb;
begin
  if not app_private.is_internal_actor() then
    raise exception using errcode = '42501', message = 'dashboard_actor_forbidden';
  end if;
  if p_max_items not between 1 and 6 then
    raise exception using errcode = '22023', message = 'invalid_dashboard_summary_limit';
  end if;

  with work as materialized (
    select * from public.my_space_items()
  ), authorized_projects as materialized (
    select p.id as project_id, p.name as project_name, p.status as project_status,
      p.target_end_date, b.name as brand_name, o.name as organization_name
    from public.projects as p
    join public.brands as b on b.id = p.brand_id
    join public.organizations as o on o.id = b.organization_id
    where p.archived_at is null
      and app_private.project_permission(p.id, 'project.view')
  )
  select jsonb_build_object(
    'work', jsonb_build_object(
      'counts', jsonb_build_object(
        'total', (select count(*) from work),
        'overdue', (select count(*) from work where bucket = 'overdue'),
        'today', (select count(*) from work where bucket = 'today'),
        'upcoming', (select count(*) from work where bucket = 'upcoming'),
        'noDueDate', (select count(*) from work where bucket = 'no_due_date')
      ),
      'nextItems', (
        select coalesce(jsonb_agg(to_jsonb(next_item)), '[]'::jsonb)
        from (
          select item_kind as "itemKind", item_id as "itemId", title, priority,
            due_at as "dueAt", bucket, project_id as "projectId", project_name as "projectName"
          from work limit p_max_items
        ) as next_item
      ),
      'overdueItems', (
        select coalesce(jsonb_agg(to_jsonb(bucket_item)), '[]'::jsonb)
        from (
          select item_kind as "itemKind", item_id as "itemId", title, priority,
            due_at as "dueAt", project_id as "projectId", project_name as "projectName"
          from work where bucket = 'overdue' limit p_max_items
        ) as bucket_item
      ),
      'todayItems', (
        select coalesce(jsonb_agg(to_jsonb(bucket_item)), '[]'::jsonb)
        from (
          select item_kind as "itemKind", item_id as "itemId", title, priority,
            due_at as "dueAt", project_id as "projectId", project_name as "projectName"
          from work where bucket = 'today' limit p_max_items
        ) as bucket_item
      ),
      'upcomingItems', (
        select coalesce(jsonb_agg(to_jsonb(bucket_item)), '[]'::jsonb)
        from (
          select item_kind as "itemKind", item_id as "itemId", title, priority,
            due_at as "dueAt", project_id as "projectId", project_name as "projectName"
          from work where bucket = 'upcoming' limit p_max_items
        ) as bucket_item
      )
    ),
    'projects', jsonb_build_object(
      'activeCount', (select count(*) from authorized_projects where project_status = 'active'),
      'attentionCount', (
        select count(*) from authorized_projects
        where project_status = 'on_hold'
          or (target_end_date < current_date and project_status not in ('completed', 'archived'))
      ),
      'items', (
        select coalesce(jsonb_agg(to_jsonb(project_item)), '[]'::jsonb)
        from (
          select project_id as "projectId", project_name as "projectName",
            project_status as status, target_end_date as "targetEndDate",
            brand_name as "brandName", organization_name as "organizationName"
          from authorized_projects
          order by target_end_date nulls last, project_name, project_id
          limit p_max_items
        ) as project_item
      )
    )
  ) into result;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.enforce_agency_membership_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  role_context text;
  department_agency uuid;
  department_category text;
begin
  select r.context into role_context
  from public.roles as r
  where r.key = new.role_key;

  select d.agency_id, d.category
  into department_agency, department_category
  from public.departments as d
  where d.id = new.department_id and d.is_active;

  if role_context is distinct from 'agency'
    or department_agency is distinct from new.agency_id
    or (new.role_key = 'agency_director' and department_category is distinct from 'direction')
    or (new.role_key <> 'agency_director' and department_category is distinct from 'operations') then
    raise exception using errcode = '22023', message = 'invalid_agency_role_department';
  end if;

  return new;
end;
$function$

