CREATE OR REPLACE FUNCTION app_private.enforce_crm_relationships()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  related_organization uuid;
  stage_outcome text;
begin
  if tg_table_name = 'opportunities' then
    if new.brand_id is not null then
      select b.organization_id into related_organization
      from public.brands as b where b.id = new.brand_id;
      if related_organization is distinct from new.organization_id then
        raise exception using errcode = '22023', message = 'brand_organization_mismatch';
      end if;
    end if;

    select ps.outcome into stage_outcome
    from public.pipeline_stages as ps
    where ps.key = new.stage_key and ps.is_active;

    if stage_outcome is null
      or (new.status = 'open' and stage_outcome <> 'open')
      or (new.status = 'won' and stage_outcome <> 'won')
      or (new.status = 'lost' and stage_outcome <> 'lost')
      or (new.status = 'archived' and stage_outcome not in ('open', 'won', 'lost')) then
      raise exception using errcode = '22023', message = 'opportunity_stage_status_mismatch';
    end if;
  elsif tg_table_name = 'crm_activities' then
    if new.brand_id is not null then
      select b.organization_id into related_organization from public.brands b where b.id = new.brand_id;
    elsif new.contact_id is not null then
      select c.organization_id into related_organization from public.contacts c where c.id = new.contact_id;
    elsif new.opportunity_id is not null then
      select o.organization_id into related_organization from public.opportunities o where o.id = new.opportunity_id;
    else
      related_organization := new.organization_id;
    end if;

    if related_organization is distinct from new.organization_id then
      raise exception using errcode = '22023', message = 'activity_organization_mismatch';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.enrich_notification_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_payload jsonb;
begin
 if new.kind='message_received' then return new; end if;
 select d.work_item_id into new.work_item_id from public.deliverables d where d.id=new.deliverable_id;
 select e.payload into v_payload from public.domain_events e where e.event_id=new.domain_event_id;
 select cp.id into new.publication_id from public.client_publications cp
 where cp.deliverable_id=new.deliverable_id
 order by (cp.id::text=v_payload->>'publication_id'
  or cp.version_id::text=v_payload->>'version_id') desc,cp.published_at desc,cp.id desc limit 1;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION app_private.ensure_general_channel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_channel uuid;
begin
 if new.lifecycle <> 'active_client' then return new; end if;
 insert into public.channels(kind,organization_id) values('organization',new.id)
 on conflict do nothing;
 select id into v_channel from public.channels where organization_id=new.id and kind='organization';
 insert into public.channel_memberships(channel_id,user_id,member_kind)
 select v_channel,cm.user_id,'client' from public.client_memberships cm
 where cm.organization_id=new.id and cm.status='active'
 on conflict(channel_id,user_id) do update set status='active',removed_at=null;
 insert into public.channel_memberships(channel_id,user_id,member_kind)
 select v_channel,am.user_id,'internal' from public.agency_memberships am
 where am.agency_id=new.agency_id and am.role_key='agency_director' and am.status='active'
 on conflict(channel_id,user_id) do update set status='active',removed_at=null;
 return new;
end; $function$

