CREATE OR REPLACE FUNCTION app_private.p13_audit(p_type text, p_actor uuid, p_resource text, p_id uuid, p_project uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
