CREATE OR REPLACE FUNCTION app_private.p13_claimed_run(p_run uuid, p_token uuid)
 RETURNS automation_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.automation_runs%rowtype;
begin
 select * into v from public.automation_runs where id=p_run for update;
 if v.id is null or v.status<>'running' or v.claim_token is distinct from p_token or v.lease_until<=now() then
  raise exception using errcode='42501',message='stale_claim'; end if;
 if not app_private.p13_permission(v.project_id,v.owner_id,'automation.manage') or not exists(
  select 1 from public.automation_definitions a where a.id=v.automation_id and a.enabled) then
  raise exception using errcode='42501',message='authorization_revoked'; end if;
 return v;
end; $function$

CREATE OR REPLACE FUNCTION app_private.p13_conditions(p_conditions jsonb, p_event domain_events)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v jsonb; v_value text;
begin
 for v in select value from jsonb_array_elements(p_conditions) loop
  v_value:=case v->>'field' when 'event_type' then p_event.event_type when 'project_id' then p_event.project_id::text
   when 'resource_type' then p_event.resource_type when 'status' then p_event.payload->>'to' end;
  if v->>'operator'='exists' and v_value is null then return false;
  elsif v->>'operator'='equals' and v_value is distinct from v->>'value' then return false;
  elsif v->>'operator'='contains' and (v_value is null or position((v->>'value') in v_value)=0) then return false;
  end if;
 end loop;
 return true;
end; $function$

CREATE OR REPLACE FUNCTION app_private.p13_dispatch_event(p_event domain_events)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.automation_definitions%rowtype; v_count integer:=0;
begin
 if p_event.project_id is null or p_event.automation_depth>=3 then return 0; end if;
 for v in select * from public.automation_definitions a where a.enabled and a.project_id=p_event.project_id
  -- Replaying an old event must not apply a definition enabled/revised afterwards.
  and a.trigger_type='domain_event' and a.event_type=p_event.event_type and a.updated_at<=p_event.occurred_at loop
  if app_private.p13_permission(v.project_id,v.created_by,'automation.manage')
   and app_private.p13_conditions(v.conditions,p_event)
   and not exists(select 1 from public.automation_runs r where r.id=p_event.origin_run_id and r.automation_id=v.id) then
   if app_private.p13_enqueue(v,p_event,null,null) is not null then v_count:=v_count+1; end if;
  end if;
 end loop;
 return v_count;
end; $function$

CREATE OR REPLACE FUNCTION app_private.p13_event_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_origin text := nullif(current_setting('omnia.automation_run',true),''); v_run public.automation_runs%rowtype;
begin
 if new.resource_type='work_item' then select project_id into new.project_id from public.work_items where id=new.resource_id;
 elsif new.resource_type='project' then new.project_id:=new.resource_id;
 elsif new.resource_type='deliverable' then select project_id into new.project_id from public.deliverables where id=new.resource_id;
 elsif new.resource_type='review_round' then
  select d.project_id into new.project_id from public.review_rounds r join public.deliverable_versions v on v.id=r.deliverable_version_id
  join public.deliverables d on d.id=v.deliverable_id where r.id=new.resource_id;
 elsif new.payload->>'project_id' ~ '^[0-9a-fA-F-]{36}$' then new.project_id:=(new.payload->>'project_id')::uuid;
 end if;
 if v_origin is not null then
  select * into v_run from public.automation_runs where id=v_origin::uuid and status='running';
  if v_run.id is null or v_run.project_id is distinct from new.project_id then
   raise exception using errcode='42501',message='automation_event_scope_forbidden'; end if;
  new.origin_run_id:=v_run.id; new.causation_id:=coalesce(v_run.event_id,v_run.id); new.correlation_id:=v_run.correlation_id;
  new.automation_depth:=v_run.depth+1;
  new.payload:=new.payload||jsonb_build_object('origin_run_id',v_run.id,'automation_id',v_run.automation_id,
   'configuration_owner',v_run.owner_id,'automation_depth',new.automation_depth);
 end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION app_private.p13_validate_definition(p_project uuid, p_actor uuid, p_trigger text, p_event text, p_conditions jsonb, p_actions jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb; v_connection uuid;
begin
 if p_trigger is null or p_trigger not in ('manual','domain_event')
  or (p_trigger='domain_event' and (p_event is null or p_event not in ('work.created','work.completed','work.status_changed','deliverable.published_to_client','review.changes_requested')))
  or (p_trigger='manual' and p_event is not null)
  or p_conditions is null or jsonb_typeof(p_conditions)<>'array' or jsonb_array_length(p_conditions)>5
  or p_actions is null or jsonb_typeof(p_actions)<>'array' or jsonb_array_length(p_actions) not between 1 and 5 then
  raise exception using errcode='22023',message='invalid_automation'; end if;
 for v in select value from jsonb_array_elements(p_conditions) loop
  if jsonb_typeof(v)<>'object' or (v-'field'-'operator'-'value')<>'{}'::jsonb
   or coalesce(v->>'field','') not in ('event_type','project_id','resource_type','status')
   or coalesce(v->>'operator','') not in ('equals','exists','contains')
   or (v->>'operator'<>'exists' and (jsonb_typeof(v->'value') is distinct from 'string' or char_length(v->>'value')>120)) then
   raise exception using errcode='22023',message='invalid_condition'; end if;
 end loop;
 for v in select value from jsonb_array_elements(p_actions) loop
  if jsonb_typeof(v)<>'object' then raise exception using errcode='22023',message='invalid_action'; end if;
  if v->>'type'='create_work_item' then
   if (v-'type'-'title'-'priority')<>'{}'::jsonb or jsonb_typeof(v->'title') is distinct from 'string'
    or char_length(btrim(v->>'title')) not between 1 and 160 or coalesce(v->>'priority','') not in ('low','normal','high','urgent')
    or not app_private.p13_permission(p_project,p_actor,'work.create') then
    raise exception using errcode='22023',message='invalid_work_action'; end if;
  elsif v->>'type'='outbound_webhook' then
   if (v-'type'-'connection_id')<>'{}'::jsonb or coalesce(v->>'connection_id','') !~ '^[0-9a-fA-F-]{36}$' then
    raise exception using errcode='22023',message='invalid_webhook_action'; end if;
   v_connection := (v->>'connection_id')::uuid;
   if not app_private.p13_permission(p_project,p_actor,'integration.view') or not exists(
    select 1 from public.integration_connections c where c.id=v_connection and c.project_id=p_project and c.status='active') then
    raise exception using errcode='42501',message='connection_scope_forbidden'; end if;
  else raise exception using errcode='22023',message='action_not_allowlisted'; end if;
 end loop;
end; $function$

CREATE OR REPLACE FUNCTION app_private.phase7_event(p_work uuid, p_type text, p_actor uuid, p_resource_type text, p_resource uuid, p_correlation uuid, p_key uuid, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare v_agency uuid; v_org uuid;
begin
  select o.agency_id,o.id into v_agency,v_org from public.work_items wi
  join public.projects p on p.id=wi.project_id join public.brands b on b.id=p.brand_id
  join public.organizations o on o.id=b.organization_id where wi.id=p_work;
  if p_work is null and p_resource_type='project' then
    select o.agency_id,o.id into v_agency,v_org from public.projects p
    join public.brands b on b.id=p.brand_id join public.organizations o on o.id=b.organization_id
    where p.id=p_resource;
  end if;
  return app_private.emit_event(p_type,p_actor,p_resource_type,p_resource,v_agency,v_org,
    p_correlation,p_key,coalesce(p_payload,'{}'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION app_private.phase7_guard_work_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare v_status text;
begin
  select d.status into v_status from public.deliverables d where d.work_item_id=new.id;
  if v_status is not null and new.status='done'
    and v_status not in ('ready_for_client','published_to_client') then
    raise exception using errcode='22023',message='deliverable_review_required'; end if;
  if v_status='in_review' and new.status not in ('in_progress') then
    raise exception using errcode='22023',message='deliverable_review_pending'; end if;
  if v_status in ('ready_for_client','published_to_client') and new.status<>'done' then
    raise exception using errcode='22023',message='deliverable_review_complete'; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION app_private.phase7_resolve_round(p_round uuid, p_work uuid, p_deliverable uuid, p_actor uuid, p_key uuid, p_correlation uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare v_status text;
begin
  if exists(select 1 from public.review_assignments a where a.review_round_id=p_round
    and a.status='changes_requested') then
    v_status := 'changes_requested';
  elsif not exists(select 1 from public.review_assignments a where a.review_round_id=p_round
    and a.status='pending') then
    v_status := 'approved';
  else return 'pending'; end if;
  update public.review_rounds set status=v_status,closed_at=now() where id=p_round and status='pending';
  if v_status='changes_requested' then
    update public.deliverables set status='changes_requested' where id=p_deliverable;
    update public.work_items set status='in_progress',completed_at=null where id=p_work;
    perform app_private.phase7_event(p_work,'review.changes_requested',p_actor,'review_round',p_round,
      p_correlation,p_key,jsonb_build_object('deliverable_id',p_deliverable));
  else
    update public.deliverables set status='ready_for_client' where id=p_deliverable;
    update public.work_items set status='done',completed_at=now() where id=p_work;
    perform app_private.phase7_event(p_work,'review.approved',p_actor,'review_round',p_round,
      p_correlation,p_key,jsonb_build_object('deliverable_id',p_deliverable));
    perform app_private.phase7_event(p_work,'deliverable.ready_for_client',p_actor,'deliverable',p_deliverable,
      p_correlation,p_key,jsonb_build_object('review_round_id',p_round));
  end if;
  return v_status;
end; $function$

CREATE OR REPLACE FUNCTION app_private.phase9_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then raise exception using errcode='23514',message='client_history_immutable'; end if;
 if tg_table_name='client_reviews' then
  if old.status<>'pending' or new.status not in ('approved','changes_requested')
   or (new.id,new.publication_id,new.context,new.opened_at)
   is distinct from (old.id,old.publication_id,old.context,old.opened_at)
   or new.closed_at is null then
   raise exception using errcode='23514',message='client_history_immutable'; end if;
 elsif tg_table_name='client_review_assignments' then
  if old.status<>'pending' or new.status not in ('approved','changes_requested')
   or (new.id,new.client_review_id,new.reviewer_id,new.assigned_at)
   is distinct from (old.id,old.client_review_id,old.reviewer_id,old.assigned_at)
   or new.resolved_at is null then
   raise exception using errcode='23514',message='client_history_immutable'; end if;
 else raise exception using errcode='23514',message='client_history_immutable'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION app_private.project_permission(p_project_id uuid, p_capability_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target_agency uuid;
  target_organization uuid;
  actor_role text;
begin
  if actor is null then return false; end if;

  select o.agency_id, o.id
  into target_agency, target_organization
  from public.projects as p
  join public.brands as b on b.id = p.brand_id
  join public.organizations as o on o.id = b.organization_id
  where p.id = p_project_id;

  if target_agency is null
    or not public.has_capability(p_capability_key, target_agency, target_organization) then
    return false;
  end if;

  select am.role_key into actor_role
  from public.agency_memberships as am
  where am.user_id = actor
    and am.agency_id = target_agency
    and am.status = 'active';

  if actor_role = 'agency_director' then return true; end if;

  return exists (
    select 1
    from public.project_memberships as pm
    where pm.project_id = p_project_id
      and pm.user_id = actor
      and pm.member_type = 'internal'
      and pm.status = 'active'
  );
end;
$function$

CREATE OR REPLACE FUNCTION app_private.promote_organization_to_client(p_organization_id uuid, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.organizations%rowtype;
  original_resource uuid;
  correlation uuid := gen_random_uuid();
begin
  select de.resource_id into original_resource
  from public.domain_events de
  where de.actor_id = actor
    and de.event_type = 'organization.promoted'
    and de.idempotency_key = p_idempotency_key;
  if original_resource is not null then return original_resource; end if;

  select * into target from public.organizations where id = p_organization_id for update;
  if target.id is null or actor is null
    or not public.has_capability('organization.promote', target.agency_id, target.id) then
    raise exception using errcode = '42501', message = 'organization_promote_forbidden';
  end if;
  if target.lifecycle <> 'prospect' then
    raise exception using errcode = '22023', message = 'organization_not_prospect';
  end if;
  if not exists (select 1 from public.brands b where b.organization_id = target.id and b.status = 'active') then
    raise exception using errcode = '22023', message = 'active_brand_required';
  end if;

  update public.organizations
  set lifecycle = 'active_client', archived_at = null
  where id = target.id;

  insert into public.crm_activities (
    organization_id, activity_type, summary, created_by, is_system_generated
  ) values (
    target.id, 'organization_promoted', 'Organization promoted to active client', actor, true
  );

  perform app_private.emit_event(
    'organization.promoted', actor, 'organization', target.id,
    target.agency_id, target.id, correlation, p_idempotency_key,
    jsonb_build_object('from', 'prospect', 'to', 'active_client')
  );
  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.push_session()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_session uuid;
begin
 if auth.uid() is null then raise exception 'unauthorized' using errcode='42501'; end if;
 begin v_session:=(auth.jwt()->>'session_id')::uuid;
 exception when invalid_text_representation then raise exception 'unauthorized' using errcode='42501'; end;
 if not exists(select 1 from auth.sessions s where s.id=v_session and s.user_id=auth.uid()
   and (s.not_after is null or s.not_after>now())) then
  raise exception 'unauthorized' using errcode='42501';
 end if;
 return v_session;
end; $function$

