CREATE OR REPLACE FUNCTION app_private.reset_dashboard_config(p_expected_revision bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
begin
  if actor is null or not app_private.is_internal_actor() then
    raise exception using errcode = '42501', message = 'dashboard_actor_forbidden';
  end if;
  if p_expected_revision < 0 then
    raise exception using errcode = '22023', message = 'invalid_dashboard_revision';
  end if;

  if p_expected_revision = 0 then
    if exists (select 1 from public.dashboard_user_configs where user_id = actor) then
      raise exception using errcode = '40001', message = 'dashboard_revision_conflict';
    end if;
    return true;
  end if;

  delete from public.dashboard_user_configs
  where user_id = actor and dashboard_key = 'main' and revision = p_expected_revision;
  if not found then
    raise exception using errcode = '40001', message = 'dashboard_revision_conflict';
  end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.revoke_project_member(p_membership_id uuid, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.project_memberships%rowtype;
  target_agency uuid;
  target_organization uuid;
  correlation uuid := gen_random_uuid();
begin
  if exists (
    select 1 from public.domain_events as de
    where de.actor_id = actor and de.event_type = 'project.member.revoked'
      and de.idempotency_key = p_idempotency_key
  ) then return p_membership_id; end if;

