CREATE OR REPLACE FUNCTION app_private.transition_work_item_core(p_work_item_id uuid, p_status text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.work_items%rowtype;
  actor_role text;
  event_name text;
  correlation uuid := gen_random_uuid();
  valid_transition boolean := false;
begin
  if exists (
    select 1 from public.domain_events as de
    where de.actor_id = actor
      and de.event_type in ('work.status_changed', 'work.completed')
      and de.resource_id = p_work_item_id
      and de.idempotency_key = p_idempotency_key
  ) then return p_work_item_id; end if;

  select * into target from public.work_items where id = p_work_item_id for update;
  if target.id is null or target.archived_at is not null
    or not app_private.project_permission(target.project_id, 'work.transition') then
    raise exception using errcode = '42501', message = 'work_transition_forbidden';
  end if;

  select am.role_key into actor_role
  from public.projects as p
  join public.brands as b on b.id = p.brand_id
  join public.organizations as o on o.id = b.organization_id
  join public.agency_memberships as am on am.agency_id = o.agency_id
  where p.id = target.project_id and am.user_id = actor and am.status = 'active';

  if actor_role = 'contributor' and not exists (
    select 1 from public.work_item_assignees as wia
    where wia.work_item_id = target.id and wia.user_id = actor
      and wia.revoked_at is null
  ) then
    raise exception using errcode = '42501', message = 'work_transition_forbidden';
  end if;

  if p_status = target.status then return target.id; end if;
  valid_transition := case target.status
    when 'todo' then p_status in ('in_progress', 'cancelled')
    when 'in_progress' then p_status in ('todo', 'blocked', 'done', 'cancelled')
    when 'blocked' then p_status in ('in_progress', 'cancelled')
    when 'done' then p_status = 'in_progress'
    when 'cancelled' then p_status = 'todo'
    else false
  end;
  if not valid_transition then
    raise exception using errcode = '22023', message = 'invalid_work_transition';
  end if;

  update public.work_items
  set status = p_status,
      completed_at = case when p_status = 'done' then now() else null end
  where id = target.id;

  event_name := case when p_status = 'done' then 'work.completed'
    else 'work.status_changed' end;
  perform app_private.record_work_event(
    target.id, event_name, actor, correlation, p_idempotency_key,
    jsonb_build_object('from', target.status, 'to', p_status)
  );
  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.update_agency_membership(p_membership_id uuid, p_role_key text, p_department_key text, p_classification text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  membership public.agency_memberships%rowtype;
  department uuid;
  department_category text;
  changed_fields text[] := array[]::text[];
  correlation uuid := gen_random_uuid();
begin
  if actor is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  select am.* into membership
  from public.agency_memberships as am
  where am.id = p_membership_id
  for update;

  if not found
    or membership.user_id = actor
    or not public.has_capability('agency.member.manage', membership.agency_id, null)
    or not public.has_capability('agency.member.role.assign', membership.agency_id, null)
    or not public.has_capability('agency.member.department.assign', membership.agency_id, null) then
    raise exception using errcode = '42501', message = 'membership_update_forbidden';
  end if;

  if exists (
    select 1 from public.domain_events as de
    where de.actor_id = actor
      and de.event_type = 'agency.member.updated'
      and de.idempotency_key = p_idempotency_key
  ) then
    return membership.id;
  end if;

  if not exists (
    select 1 from public.roles as r where r.key = p_role_key and r.context = 'agency'
  ) or p_classification not in ('founder', 'employee', 'external_collaborator', 'contractor') then
    raise exception using errcode = '22023', message = 'invalid_membership_input';
  end if;

  select d.id, d.category into department, department_category
  from public.departments as d
  where d.agency_id = membership.agency_id and d.key = p_department_key and d.is_active;

  if department is null
    or (p_role_key = 'agency_director' and department_category <> 'direction')
    or (p_role_key <> 'agency_director' and department_category <> 'operations') then
    raise exception using errcode = '22023', message = 'invalid_agency_role_department';
  end if;

  if membership.role_key is distinct from p_role_key then
    changed_fields := array_append(changed_fields, 'role');
  end if;
  if membership.department_id is distinct from department then
    changed_fields := array_append(changed_fields, 'department');
  end if;
  if membership.classification is distinct from p_classification then
    changed_fields := array_append(changed_fields, 'classification');
  end if;

  update public.agency_memberships
  set role_key = p_role_key,
      department_id = department,
      classification = p_classification
  where id = membership.id;

  perform app_private.emit_event(
    'agency.member.updated', actor, 'agency_membership', membership.id,
    membership.agency_id, null, correlation, p_idempotency_key,
    jsonb_build_object('changed_fields', to_jsonb(changed_fields))
  );

  return membership.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.update_milestone(p_milestone_id uuid, p_name text, p_description text, p_due_date date, p_status text, p_sort_order integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.milestones%rowtype;
  correlation uuid := gen_random_uuid();
begin
  select * into target from public.milestones where id = p_milestone_id for update;
  if target.id is null
    or not app_private.project_permission(target.project_id, 'milestone.manage')
    or exists (
      select 1 from public.projects as p
      where p.id = target.project_id and p.archived_at is not null
    ) then
    raise exception using errcode = '42501', message = 'milestone_update_forbidden';
  end if;
  if p_status not in ('planned', 'in_progress', 'completed', 'closed', 'archived')
    or char_length(btrim(p_name)) not between 1 and 160 or p_sort_order < 0 then
    raise exception using errcode = '22023', message = 'invalid_milestone_input';
  end if;

  update public.milestones
  set name = btrim(p_name), description = nullif(btrim(p_description), ''),
      due_date = p_due_date, status = p_status, sort_order = p_sort_order,
      archived_at = case when p_status = 'archived' then coalesce(archived_at, now()) else null end
  where id = target.id;

  perform app_private.emit_event(
    'milestone.updated', actor, 'milestone', target.id,
    (select o.agency_id from public.projects p join public.brands b on b.id=p.brand_id join public.organizations o on o.id=b.organization_id where p.id=target.project_id),
    (select b.organization_id from public.projects p join public.brands b on b.id=p.brand_id where p.id=target.project_id),
    correlation, null, jsonb_build_object('project_id', target.project_id, 'status', p_status)
  );
  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.update_organization(p_organization_id uuid, p_name text, p_domain text, p_timezone text, p_lifecycle text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.organizations%rowtype;
  correlation uuid := gen_random_uuid();
begin
  select * into target from public.organizations where id = p_organization_id for update;
  if target.id is null
    or actor is null
    or not public.has_capability('organization.manage', target.agency_id, target.id) then
    raise exception using errcode = '42501', message = 'organization_manage_forbidden';
  end if;
  if p_lifecycle not in ('prospect', 'active_client', 'inactive')
    or char_length(btrim(p_name)) not between 1 and 200
    or char_length(btrim(p_timezone)) not between 1 and 80 then
    raise exception using errcode = '22023', message = 'invalid_organization_input';
  end if;
  if target.lifecycle = 'prospect' and p_lifecycle = 'active_client' then
    raise exception using errcode = '22023', message = 'organization_promotion_command_required';
  end if;

  update public.organizations
  set name = btrim(p_name), domain = nullif(btrim(p_domain), ''),
      timezone = btrim(p_timezone), lifecycle = p_lifecycle, archived_at = null
  where id = target.id;

  perform app_private.emit_event(
    'organization.updated', actor, 'organization', target.id,
    target.agency_id, target.id, correlation, null,
    jsonb_build_object('lifecycle', p_lifecycle)
  );
  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.validate_dashboard_config(p_registry_version integer, p_widget_instances jsonb, p_responsive_layouts jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  instance jsonb;
  item jsonb;
  config jsonb;
  layout jsonb;
  instance_id text;
  widget_key text;
  widget_version integer;
  breakpoint text;
  cols integer;
  item_x integer;
  item_y integer;
  item_w integer;
  item_h integer;
  min_width integer;
  max_width integer;
  min_height integer;
  max_height integer;
  seen_instance_ids text[] := '{}'::text[];
  seen_widget_keys text[] := '{}'::text[];
  active_instance_ids text[] := '{}'::text[];
  seen_layout_ids text[];
  instance_count integer;
begin
  if (select auth.uid()) is null or not app_private.is_internal_actor() then
    raise exception using errcode = '42501', message = 'dashboard_actor_forbidden';
  end if;

  if p_registry_version is distinct from 1 then
    raise exception using errcode = '22023', message = 'invalid_dashboard_registry_version';
  end if;

  if jsonb_typeof(p_widget_instances) is distinct from 'array' then
    raise exception using errcode = '22023', message = 'invalid_dashboard_widget_instances';
  end if;

  instance_count := jsonb_array_length(p_widget_instances);
  if instance_count > 12 then
    raise exception using errcode = '22023', message = 'dashboard_widget_limit_exceeded';
  end if;

  for instance in select value from jsonb_array_elements(p_widget_instances)
  loop
    if jsonb_typeof(instance) is distinct from 'object'
      or exists (
        select 1 from jsonb_object_keys(instance) as key
        where key not in ('instanceId', 'widgetKey', 'widgetVersion', 'config', 'enabled')
      ) then
      raise exception using errcode = '22023', message = 'invalid_dashboard_widget_instance';
    end if;

    instance_id := instance ->> 'instanceId';
    widget_key := instance ->> 'widgetKey';

    if instance_id is null
      or instance_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception using errcode = '22023', message = 'invalid_dashboard_instance_id';
    end if;
    if instance_id = any(seen_instance_ids) then
      raise exception using errcode = '22023', message = 'duplicate_dashboard_instance_id';
    end if;

    if widget_key not in (
      'my-work-summary', 'overdue-work', 'today-work', 'upcoming-work',
      'projects', 'crm-opportunities', 'crm-organizations', 'quick-actions'
    ) then
      raise exception using errcode = '22023', message = 'unknown_dashboard_widget';
    end if;
    if widget_key = any(seen_widget_keys) then
      raise exception using errcode = '22023', message = 'duplicate_dashboard_widget';
    end if;

    if jsonb_typeof(instance -> 'widgetVersion') is distinct from 'number'
      or (instance ->> 'widgetVersion') !~ '^[0-9]+$' then
      raise exception using errcode = '22023', message = 'invalid_dashboard_widget_version';
    end if;
    widget_version := (instance ->> 'widgetVersion')::integer;
    if widget_version <> 1 then
      raise exception using errcode = '22023', message = 'invalid_dashboard_widget_version';
    end if;

    if jsonb_typeof(instance -> 'enabled') is distinct from 'boolean' then
      raise exception using errcode = '22023', message = 'invalid_dashboard_widget_enabled';
    end if;

    config := instance -> 'config';
    if jsonb_typeof(config) is distinct from 'object' then
      raise exception using errcode = '22023', message = 'invalid_dashboard_widget_config';
    end if;
    if widget_key = 'quick-actions' then
      if config <> '{}'::jsonb then
        raise exception using errcode = '22023', message = 'invalid_dashboard_widget_config';
      end if;
    else
      if exists (
        select 1 from jsonb_object_keys(config) as key where key <> 'maxItems'
      ) or (
        config ? 'maxItems'
        and (
          jsonb_typeof(config -> 'maxItems') is distinct from 'number'
          or (config ->> 'maxItems') !~ '^[1-6]$'
        )
      ) then
        raise exception using errcode = '22023', message = 'invalid_dashboard_widget_config';
      end if;
    end if;

    if widget_key = 'crm-opportunities'
      and not exists (
        select 1 from public.my_capabilities() as capability
        where capability.capability_key = 'opportunity.view'
      ) then
      raise exception using errcode = '42501', message = 'dashboard_widget_forbidden';
    end if;
    if widget_key = 'crm-organizations'
      and not exists (
        select 1 from public.my_capabilities() as capability
        where capability.capability_key = 'organization.view'
      ) then
      raise exception using errcode = '42501', message = 'dashboard_widget_forbidden';
    end if;

    seen_instance_ids := array_append(seen_instance_ids, instance_id);
    seen_widget_keys := array_append(seen_widget_keys, widget_key);
    if (instance ->> 'enabled')::boolean then
      active_instance_ids := array_append(active_instance_ids, instance_id);
    end if;
  end loop;

  if jsonb_typeof(p_responsive_layouts) is distinct from 'object'
    or not (p_responsive_layouts ?& array['desktop', 'tablet', 'mobile'])
    or exists (
      select 1 from jsonb_object_keys(p_responsive_layouts) as key
      where key not in ('desktop', 'tablet', 'mobile')
    ) then
    raise exception using errcode = '22023', message = 'invalid_dashboard_breakpoints';
  end if;

  foreach breakpoint in array array['desktop', 'tablet', 'mobile']
  loop
    cols := case breakpoint when 'desktop' then 12 when 'tablet' then 6 else 1 end;
    layout := p_responsive_layouts -> breakpoint;
    seen_layout_ids := '{}'::text[];

    if jsonb_typeof(layout) is distinct from 'array' then
      raise exception using errcode = '22023', message = 'invalid_dashboard_layout';
    end if;

    for item in select value from jsonb_array_elements(layout)
    loop
      if jsonb_typeof(item) is distinct from 'object'
        or exists (
          select 1 from jsonb_object_keys(item) as key
          where key not in ('i', 'x', 'y', 'w', 'h')
        ) then
        raise exception using errcode = '22023', message = 'invalid_dashboard_layout_item';
      end if;

      instance_id := item ->> 'i';
      if instance_id is null or not (instance_id = any(active_instance_ids)) then
        raise exception using errcode = '22023', message = 'unknown_dashboard_layout_instance';
      end if;
      if instance_id = any(seen_layout_ids) then
        raise exception using errcode = '22023', message = 'duplicate_dashboard_layout_instance';
      end if;

      if jsonb_typeof(item -> 'x') is distinct from 'number'
        or jsonb_typeof(item -> 'y') is distinct from 'number'
        or jsonb_typeof(item -> 'w') is distinct from 'number'
        or jsonb_typeof(item -> 'h') is distinct from 'number'
        or (item ->> 'x') !~ '^-?[0-9]+$'
        or (item ->> 'y') !~ '^-?[0-9]+$'
        or (item ->> 'w') !~ '^-?[0-9]+$'
        or (item ->> 'h') !~ '^-?[0-9]+$' then
        raise exception using errcode = '22023', message = 'invalid_dashboard_layout_number';
      end if;

      item_x := (item ->> 'x')::integer;
      item_y := (item ->> 'y')::integer;
      item_w := (item ->> 'w')::integer;
      item_h := (item ->> 'h')::integer;
      select value ->> 'widgetKey' into widget_key
      from jsonb_array_elements(p_widget_instances)
      where value ->> 'instanceId' = instance_id;

      min_width := case widget_key
        when 'my-work-summary' then 4
        when 'projects' then 4
        else 3
      end;
      max_width := case widget_key
        when 'my-work-summary' then 12
        when 'projects' then 12
        when 'crm-opportunities' then 12
        when 'crm-organizations' then 12
        else 6
      end;
      min_height := case widget_key when 'projects' then 3 else 2 end;
      max_height := case widget_key
        when 'projects' then 6
        when 'crm-opportunities' then 5
        when 'crm-organizations' then 5
        when 'quick-actions' then 3
        else 4
      end;

      if item_x < 0 or item_y < 0 or item_w < 1 or item_h < min_height
        or item_h > max_height or item_x + item_w > cols then
        raise exception using errcode = '22023', message = 'dashboard_layout_out_of_bounds';
      end if;
      if breakpoint = 'mobile' then
        if item_x <> 0 or item_w <> 1 then
          raise exception using errcode = '22023', message = 'invalid_dashboard_mobile_layout';
        end if;
      elsif item_w < least(min_width, cols) or item_w > least(max_width, cols) then
        raise exception using errcode = '22023', message = 'unsupported_dashboard_widget_size';
      end if;

      seen_layout_ids := array_append(seen_layout_ids, instance_id);
    end loop;

    if coalesce(array_length(seen_layout_ids, 1), 0)
      <> coalesce(array_length(active_instance_ids, 1), 0) then
      raise exception using errcode = '22023', message = 'incomplete_dashboard_layout';
    end if;

    if exists (
      select 1
      from jsonb_array_elements(layout) with ordinality as a(item, position)
      join jsonb_array_elements(layout) with ordinality as b(item, position)
        on a.position < b.position
      where (a.item ->> 'x')::integer < (b.item ->> 'x')::integer + (b.item ->> 'w')::integer
        and (a.item ->> 'x')::integer + (a.item ->> 'w')::integer > (b.item ->> 'x')::integer
        and (a.item ->> 'y')::integer < (b.item ->> 'y')::integer + (b.item ->> 'h')::integer
        and (a.item ->> 'y')::integer + (a.item ->> 'h')::integer > (b.item ->> 'y')::integer
    ) then
      raise exception using errcode = '22023', message = 'overlapping_dashboard_layout';
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_editorial_application(application_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); work_id uuid; target public.editorial_items%rowtype;
  application public.work_applications%rowtype; correlation uuid := gen_random_uuid(); rejected record;
begin
  select ei.work_item_id into work_id from public.work_applications wa
  join public.editorial_items ei on ei.id=wa.editorial_item_id where wa.id=application_id;
  perform 1 from public.work_items wi where wi.id=work_id for update;
  select wa.* into application from public.work_applications wa where wa.id=application_id for update;
  select ei.* into target from public.editorial_items ei where ei.id=application.editorial_item_id for update;
  if actor is not null and target.id is not null and application.status='accepted'
    and target.planning_state='assigned'
    and app_private.editorial_permission(target.project_id,'editorial.assign')
    and exists(select 1 from public.work_item_assignees wia where wia.work_item_id=work_id
      and wia.user_id=application.applicant_id and wia.revoked_at is null) then
    return work_id;
  end if;
  if actor is null or target.id is null or application.status <> 'pending' or target.planning_state <> 'available'
    or not app_private.editorial_permission(target.project_id,'editorial.assign')
    or not app_private.editorial_permission(target.project_id,'work.assign')
    or not app_private.editorial_applicant_eligible(target.project_id,application.applicant_id)
    or exists(select 1 from public.work_item_assignees wia where wia.work_item_id=work_id and wia.revoked_at is null)
    or exists(select 1 from public.work_items wi where wi.id=work_id and (wi.archived_at is not null or wi.status <> 'todo')) then
    raise exception using errcode='42501', message='editorial_accept_forbidden';
  end if;
  perform 1 from public.project_memberships pm where pm.project_id=target.project_id
    and pm.user_id=application.applicant_id and pm.status='active' and pm.member_type='internal' for share;
  perform app_private.assign_work_item_core(work_id,array[application.applicant_id],gen_random_uuid());
  update public.work_applications set status='accepted',resolved_at=now(),resolved_by=actor where id=application_id;
  perform app_private.record_editorial_event(target.project_id,'editorial.application.accepted','work_application',application_id,actor,correlation,null,
    jsonb_build_object('editorial_item_id',target.id,'applicant_id',application.applicant_id));
  for rejected in update public.work_applications set status='rejected',resolved_at=now(),resolved_by=actor
    where editorial_item_id=target.id and id<>application_id and status='pending' returning id loop
    perform app_private.record_editorial_event(target.project_id,'editorial.application.rejected','work_application',rejected.id,actor,correlation,null,
      jsonb_build_object('editorial_item_id',target.id));
  end loop;
  update public.editorial_items set planning_state='assigned' where id=target.id;
  perform app_private.record_editorial_event(target.project_id,'editorial.item.assigned','editorial_item',target.id,actor,correlation,null,
    jsonb_build_object('work_item_id',work_id,'applicant_id',application.applicant_id));
  return work_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_channel_member(p_channel uuid, p_user uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_c public.channels%rowtype; v_kind text; v_id uuid;
begin
 select * into v_c from public.channels where id=p_channel and archived_at is null for update;
 if v_c.id is null or not app_private.can_manage_channel(p_channel) then
  raise exception using errcode='42501',message='channel_member_forbidden'; end if;
 if v_c.kind='project' then
  if exists(select 1 from public.project_memberships pm where pm.project_id=v_c.project_id
     and pm.user_id=p_user and pm.member_type='client' and pm.status='active')
     and exists(select 1 from public.client_memberships cm where cm.organization_id=v_c.organization_id
      and cm.user_id=p_user and cm.status='active') then v_kind:='client';
  elsif exists(select 1 from public.project_memberships pm where pm.project_id=v_c.project_id
     and pm.user_id=p_user and pm.member_type='internal' and pm.status='active')
     and exists(select 1 from public.agency_memberships am join public.organizations o on o.agency_id=am.agency_id
      where o.id=v_c.organization_id and am.user_id=p_user and am.status='active') then v_kind:='internal';
  end if;
 else
  if exists(select 1 from public.client_memberships cm where cm.organization_id=v_c.organization_id
    and cm.user_id=p_user and cm.status='active') then v_kind:='client';
  elsif exists(select 1 from public.agency_memberships am join public.organizations o on o.agency_id=am.agency_id
    where o.id=v_c.organization_id and am.user_id=p_user and am.status='active') then v_kind:='internal'; end if;
 end if;
 if v_kind is null then raise exception using errcode='42501',message='channel_member_ineligible'; end if;
 insert into public.channel_memberships(channel_id,user_id,member_kind,added_by)
 values(p_channel,p_user,v_kind,auth.uid()) on conflict(channel_id,user_id)
 do update set status='active',removed_at=null,member_kind=excluded.member_kind
 returning id into v_id;
 perform app_private.emit_event('channel.member.added',auth.uid(),'channel_membership',v_id,null,v_c.organization_id,
 gen_random_uuid(),null,jsonb_build_object('channel_id',p_channel,'user_id',p_user));
 return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.add_client_feedback(publication_id uuid, body text, idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare v_actor uuid:=auth.uid(); v_cp public.client_publications%rowtype;
 v_prior public.client_feedback%rowtype; v_id uuid;
begin
 if v_actor is null or idempotency_key is null or char_length(btrim(coalesce(body,''))) not between 1 and 4000 then
  raise exception using errcode='22023',message='invalid_client_feedback'; end if;
 select * into v_cp from public.client_publications cp where cp.id=publication_id;
 if v_cp.id is null or not app_private.client_project_access(v_cp.project_id,v_actor) then
  raise exception using errcode='42501',message='client_feedback_forbidden'; end if;
 select * into v_prior from public.client_feedback cf where cf.author_id=v_actor and cf.idempotency_key=idempotency_key;
 if v_prior.id is not null then
  if v_prior.publication_id<>publication_id or v_prior.body<>btrim(body) then
   raise exception using errcode='22023',message='idempotency_key_conflict'; end if;
  return v_prior.id;
 end if;
 insert into public.client_feedback(publication_id,author_id,body,idempotency_key)
  values(publication_id,v_actor,btrim(body),idempotency_key) returning id into v_id;
 perform app_private.phase7_event((select d.work_item_id from public.deliverables d where d.id=v_cp.deliverable_id),
  'client.feedback.added',v_actor,'client_feedback',v_id,gen_random_uuid(),idempotency_key,
  jsonb_build_object('publication_id',publication_id));
 return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.apply_to_editorial_work(item_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); target public.editorial_items%rowtype; work_id uuid; created uuid;
begin
  select ei.work_item_id into work_id from public.editorial_items ei where ei.id=item_id;
  perform 1 from public.work_items wi where wi.id=work_id for update;
  select * into target from public.editorial_items ei where ei.id=item_id for update;
  if actor is null or target.id is null or target.planning_state <> 'available'
    or not app_private.editorial_permission(target.project_id,'editorial.apply')
    or not app_private.editorial_applicant_eligible(target.project_id,actor) then
    raise exception using errcode='42501', message='editorial_apply_forbidden';
  end if;
  perform 1 from public.project_memberships pm where pm.project_id=target.project_id and pm.user_id=actor
    and pm.status='active' and pm.member_type='internal' for share;
  if exists(select 1 from public.work_applications wa where wa.editorial_item_id=item_id and wa.applicant_id=actor) then
    select wa.id into created from public.work_applications wa where wa.editorial_item_id=item_id and wa.applicant_id=actor;
    return created;
  end if;
  insert into public.work_applications(editorial_item_id,applicant_id) values(item_id,actor) returning id into created;
  perform app_private.record_editorial_event(target.project_id,'editorial.application.created','work_application',created,actor,gen_random_uuid(),null,
    jsonb_build_object('editorial_item_id',item_id));
  return created;
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_editorial_item(item_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); target public.editorial_items%rowtype; work_id uuid; rejected record;
begin
  select ei.work_item_id into work_id from public.editorial_items ei where ei.id=item_id;
  perform 1 from public.work_items wi where wi.id=work_id for update;
  select * into target from public.editorial_items ei where ei.id=item_id for update;
  if actor is null or target.id is null or target.archived_at is not null
    or not app_private.editorial_permission(target.project_id,'editorial.archive') then
    raise exception using errcode='42501', message='editorial_archive_forbidden';
  end if;
  for rejected in update public.work_applications set status='rejected',resolved_at=now(),resolved_by=actor
    where editorial_item_id=item_id and status='pending' returning id loop
    perform app_private.record_editorial_event(target.project_id,'editorial.application.rejected','work_application',rejected.id,actor,gen_random_uuid(),null,
      jsonb_build_object('editorial_item_id',item_id,'reason','archived'));
  end loop;
  update public.editorial_items set planning_state='cancelled',archived_at=now() where id=item_id;
  perform app_private.record_editorial_event(target.project_id,'editorial.item.archived','editorial_item',item_id,actor,gen_random_uuid(),null,'{}');
  return item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_file_asset(asset_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_asset public.file_assets%rowtype;
begin
 select * into v_asset from public.file_assets where id=asset_id for update;
 if auth.uid() is null or v_asset.id is null or not app_private.project_permission(v_asset.project_id,'file.archive')
 then raise exception using errcode='42501',message='file_archive_forbidden'; end if;
 if v_asset.status='archived' then return asset_id; end if;
 if v_asset.status<>'ready' then raise exception using errcode='22023',message='file_not_ready'; end if;
 update public.file_assets set status='archived',archived_at=now() where id=asset_id;
 perform app_private.file_event(asset_id,'file.archived');
 return asset_id;
end; $function$

CREATE OR REPLACE FUNCTION public.archive_personal_work_item(personal_item_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.personal_work_items%rowtype;
begin
  select * into target
  from public.personal_work_items where id = personal_item_id for update;
  if actor is null or target.id is null or target.user_id <> actor
    or not app_private.is_internal_actor()
    or not public.has_capability('personal_work.manage', null, null) then
    raise exception using errcode = '42501', message = 'personal_work_archive_forbidden';
  end if;
  if target.status <> 'archived' then
    update public.personal_work_items
    set status = 'archived', completed_at = null, archived_at = now()
    where id = target.id;
  end if;
  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.configure_review_requirements(project_id uuid, deliverable_id uuid, reviewer_ids uuid[], idempotency_key uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare v_actor uuid := (select auth.uid()); v_project public.projects%rowtype;
  v_reviewer uuid; v_correlation uuid := gen_random_uuid(); v_count integer;
begin
  if v_actor is null or idempotency_key is null or reviewer_ids is null
    or cardinality(reviewer_ids) not between 1 and 12
    or array_position(reviewer_ids,null) is not null
    or (select count(distinct x) from unnest(reviewer_ids) x)<>cardinality(reviewer_ids) then
    raise exception using errcode='22023',message='invalid_review_configuration'; end if;
  select * into v_project from public.projects where id=project_id for update;
  if v_project.id is null or v_project.archived_at is not null
    or not app_private.project_permission(project_id,'review.configure') then
    raise exception using errcode='42501',message='review_configure_forbidden'; end if;
  if deliverable_id is not null and not exists(select 1 from public.deliverables d
    where d.id=deliverable_id and d.project_id=project_id and d.archived_at is null) then
    raise exception using errcode='22023',message='invalid_review_deliverable'; end if;
  if deliverable_id is not null then
    perform 1 from public.deliverables d where d.id=deliverable_id for update;
  end if;
  -- Same key is a true retry only for the same target and reviewer set.
  if exists(select 1 from public.domain_events e where e.actor_id=v_actor
    and e.event_type='review.requirements.configured' and e.idempotency_key=idempotency_key) then
    if not exists(select 1 from public.domain_events e where e.actor_id=v_actor
      and e.event_type='review.requirements.configured' and e.idempotency_key=idempotency_key
      and e.payload->>'project_id'=project_id::text
      and e.payload->>'deliverable_id'=coalesce(deliverable_id::text,'')
      and e.payload->'reviewer_ids'=to_jsonb((select array_agg(x order by x) from unnest(reviewer_ids) x))) then
      raise exception using errcode='22023',message='idempotency_key_conflict'; end if;
    return cardinality(reviewer_ids);
  end if;
  foreach v_reviewer in array reviewer_ids loop
    if not app_private.phase7_reviewer_eligible(project_id,v_reviewer) then
      raise exception using errcode='22023',message='reviewer_not_eligible'; end if;
  end loop;
  update public.review_requirements set active=false,retired_at=now()
  where review_requirements.project_id=configure_review_requirements.project_id
    and review_requirements.deliverable_id is not distinct from configure_review_requirements.deliverable_id
    and active;
  insert into public.review_requirements(project_id,deliverable_id,reviewer_id,created_by)
  select configure_review_requirements.project_id,configure_review_requirements.deliverable_id,x,v_actor
  from unnest(reviewer_ids) x;
  v_count := cardinality(reviewer_ids);
  perform app_private.phase7_event(
    (select d.work_item_id from public.deliverables d where d.id=deliverable_id),
    'review.requirements.configured',v_actor,'project',project_id,v_correlation,idempotency_key,
    jsonb_build_object('project_id',project_id,'deliverable_id',coalesce(deliverable_id::text,''),
      'reviewer_ids',(select to_jsonb(array_agg(x order by x)) from unnest(reviewer_ids) x)));
  return v_count;
end; $function$

CREATE OR REPLACE FUNCTION public.confirm_file_permanent_delete(asset_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_asset public.file_assets%rowtype;
begin
 select * into v_asset from public.file_assets where id=asset_id for update;
 if auth.uid() is null or v_asset.id is null or v_asset.status<>'deleting'
   or not app_private.file_director_permission(v_asset.project_id)
   or exists(select 1 from public.deliverable_files df where df.asset_id=v_asset.id)
   or exists(select 1 from public.content_asset_links cal where cal.asset_id=v_asset.id)
 then raise exception using errcode='42501',message='file_delete_forbidden'; end if;
 if exists(select 1 from storage.objects where bucket_id=v_asset.bucket_id and name=v_asset.object_path)
 then raise exception using errcode='22023',message='file_object_still_present'; end if;
 update public.file_assets set status='deleted',deleted_at=now() where id=asset_id;
 perform app_private.file_event(asset_id,'file.deleted_permanently');
 return asset_id;
end; $function$

