CREATE OR REPLACE FUNCTION public.export_analytics(p_section text, p_from date, p_to date, p_agency uuid DEFAULT NULL::uuid, p_organization uuid DEFAULT NULL::uuid, p_brand uuid DEFAULT NULL::uuid, p_project uuid DEFAULT NULL::uuid, p_currency text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform app_private.analytics_validate(p_from,p_to);
 perform 1 from app_private.analytics_scope(p_agency,p_organization,p_brand,p_project);
 if not exists(select 1 from public.my_capabilities() c where c.capability_key='analytics.export') or exists(select 1 from
  app_private.analytics_scope(p_agency,p_organization,p_brand,p_project) s where not app_private.project_permission(s.project_id,'analytics.export')) then
  raise exception using errcode='42501',message='analytics_export_forbidden'; end if;
 case p_section
  when 'overview' then return public.analytics_overview(p_from,p_to,p_agency,p_organization,p_brand,p_project);
  when 'work' then return public.analytics_work(p_from,p_to,p_agency,p_organization,p_brand,p_project);
  when 'editorial' then return public.analytics_editorial(p_from,p_to,p_agency,p_organization,p_brand,p_project);
  when 'reviews' then return public.analytics_reviews(p_from,p_to,p_agency,p_organization,p_brand,p_project);
  when 'billing' then return public.analytics_billing(p_from,p_to,p_agency,p_organization,p_brand,p_project,p_currency);
  else raise exception using errcode='22023',message='invalid_analytics_export';
 end case;
end; $function$

CREATE OR REPLACE FUNCTION public.finalize_file_asset(asset_id uuid)
 RETURNS file_assets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_asset public.file_assets%rowtype; v_object storage.objects%rowtype;
begin
 select * into v_asset from public.file_assets where id=asset_id for update;
 if auth.uid() is null or v_asset.id is null or v_asset.uploaded_by<>auth.uid()
   or not app_private.project_permission(v_asset.project_id,'file.upload')
 then raise exception using errcode='42501',message='file_finalize_forbidden'; end if;
 if v_asset.status='ready' then return v_asset; end if;
 if v_asset.status<>'pending' then raise exception using errcode='22023',message='file_not_pending'; end if;
 select * into v_object from storage.objects where bucket_id=v_asset.bucket_id and name=v_asset.object_path;
 if v_object.id is null or lower(coalesce(v_object.metadata->>'mimetype',''))<>lower(v_asset.mime_type)
   or (v_object.metadata->>'size')::bigint is distinct from v_asset.size_bytes
 then raise exception using errcode='22023',message='file_object_mismatch'; end if;
 update public.file_assets set status='ready',finalized_at=now() where id=asset_id returning * into v_asset;
 insert into public.project_files(project_id,asset_id,linked_by) values(v_asset.project_id,asset_id,auth.uid());
 perform app_private.file_event(asset_id,'file.upload.finalized');
 return v_asset;
end; $function$

CREATE OR REPLACE FUNCTION public.issue_billing_document(p_document_id uuid, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target_doc public.billing_documents%rowtype;
  target_organization uuid;
  target_agency uuid;
  new_number text;
  year_str text := to_char(now(), 'YYYY');
  seq_num int;
  created_event uuid;
begin
  perform app_private.assert_billing_command(p_document_id,'billing.issue',p_idempotency_key);
  if p_idempotency_key is not null then
    select de.resource_id into created_event
    from public.domain_events as de
    where de.actor_id = actor
      and de.event_type = 'billing.document.issued'
      and de.idempotency_key = p_idempotency_key;
    if created_event is not null then
      if created_event<>p_document_id then raise exception using errcode='22023',message='idempotency_conflict'; end if;
      return created_event; end if;
  end if;

  select * into target_doc from public.billing_documents where id = p_document_id for update;
  if target_doc.id is null then raise exception using errcode = 'P0001', message = 'not_found'; end if;
  if target_doc.status <> 'draft' then raise exception using errcode = 'P0001', message = 'not_draft'; end if;

  select o.id, o.agency_id into target_organization, target_agency
  from public.organizations o where o.id = target_doc.organization_id;

  if not public.is_internal_actor() then raise exception using errcode = '42501', message = 'forbidden'; end if;
  if target_doc.project_id is not null and not public.project_access_allowed(target_doc.project_id, 'billing.issue') then
    if not public.has_capability('billing.issue', target_agency, target_organization) then
      raise exception using errcode = '42501', message = 'forbidden';
    end if;
  elsif target_doc.project_id is null and not public.has_capability('billing.issue', target_agency, target_organization) then
    raise exception using errcode = '42501', message = 'forbidden';
  end if;

  -- Verify total math
  if target_doc.total_amount <> (target_doc.subtotal_amount + target_doc.tax_amount) then
    raise exception using errcode = '23514', message = 'invalid_totals';
  end if;
  
  -- Verify items total math
  declare
    items_total numeric(14,2);
  begin
    select coalesce(sum(line_total), 0) into items_total from public.billing_document_items where billing_document_id = p_document_id;
    if items_total <> target_doc.subtotal_amount then
       raise exception using errcode = '23514', message = 'items_total_mismatch';
    end if;
  end;

  seq_num := nextval('public.billing_document_seq');
  new_number := 'OMNIA-' || year_str || '-' || lpad(seq_num::text, 6, '0');

  update public.billing_documents
  set status = 'issued',
      number = new_number,
      issued_at = now(),
      issued_by = actor
  where id = p_document_id;

  perform app_private.emit_event(
    'billing.document.issued', actor, 'billing_document', p_document_id,
    target_agency, target_organization, p_document_id, p_idempotency_key, '{}'::jsonb
  );

  return p_document_id;
end;
$function$

