CREATE OR REPLACE FUNCTION public.phase13_retry_run(p_run uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.automation_runs%rowtype;
begin
 select * into v from public.automation_runs where id=p_run for update;
 if v.id is null or not app_private.p13_permission(v.project_id,(select auth.uid()),'automation.run') then
  raise exception using errcode='42501',message='automation_forbidden'; end if;
 if v.status<>'failed' or v.manual_retries>=3 or not exists(select 1 from public.automation_definitions a where a.id=v.automation_id and a.enabled) then
  raise exception using errcode='22023',message='retry_not_allowed'; end if;
 perform pg_advisory_xact_lock(hashtextextended('p13.retry.'||(select auth.uid())::text,0));
 if (select count(*) from public.audit_events where actor_id=(select auth.uid()) and event_type='automation.retried' and occurred_at>now()-interval '1 minute')>=10 then
  raise exception using errcode='54000',message='rate_limited'; end if;
 update public.automation_runs set status='pending',max_attempt=attempt+3,manual_retries=manual_retries+1,
  next_attempt_at=now(),finished_at=null,claim_token=null,lease_until=null where id=v.id;
 update public.automation_run_steps set status='pending' where run_id=v.id and status in ('failed','running');
 perform app_private.p13_audit('automation.retried',(select auth.uid()),'automation_run',v.id,v.project_id,
  jsonb_build_object('automation_id',v.automation_id,'next_attempt',v.attempt+1));
end; $function$

CREATE OR REPLACE FUNCTION public.phase13_save_automation(p_project uuid, p_name text, p_enabled boolean, p_trigger text, p_event text, p_conditions jsonb, p_actions jsonb, p_key uuid, p_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_actor uuid := (select auth.uid()); v_owner uuid;
begin
 if not app_private.p13_permission(p_project,v_actor,'automation.manage') then
  raise exception using errcode='42501',message='automation_forbidden'; end if;
 if p_name is null or char_length(btrim(p_name)) not between 1 and 120 or p_enabled is null or p_key is null then
  raise exception using errcode='22023',message='invalid_automation'; end if;
 v_owner := v_actor;
 if p_id is not null then
  select id,created_by into v_id,v_owner from public.automation_definitions where id=p_id and project_id=p_project for update;
  if v_id is null then raise exception using errcode='42501',message='automation_forbidden'; end if;
 end if;
 perform app_private.p13_validate_definition(p_project,v_owner,p_trigger,p_event,p_conditions,p_actions);
 if p_id is null then
  insert into public.automation_definitions(project_id,name,enabled,trigger_type,event_type,conditions,actions,created_by,create_key)
  values(p_project,btrim(p_name),p_enabled,p_trigger,p_event,p_conditions,p_actions,v_actor,p_key)
  on conflict(created_by,create_key) do nothing returning id into v_id;
  if v_id is null then
   select id into v_id from public.automation_definitions where created_by=v_actor and create_key=p_key and project_id=p_project;
   if v_id is null then raise exception using errcode='22023',message='idempotency_conflict'; end if;
   return v_id;
  end if;
 else
  update public.automation_definitions set name=btrim(p_name),enabled=p_enabled,trigger_type=p_trigger,event_type=p_event,
   conditions=p_conditions,actions=p_actions,revision=revision+1,updated_at=now() where id=v_id;
 end if;
 perform app_private.p13_audit(case when p_enabled then 'automation.enabled' else 'automation.disabled' end,
  v_actor,'automation',v_id,p_project,jsonb_build_object('owner_id',v_owner));
 return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.phase13_save_connection(p_project uuid, p_name text, p_key uuid, p_id uuid DEFAULT NULL::uuid, p_events text[] DEFAULT ARRAY['work.created'::text, 'work.completed'::text, 'work.status_changed'::text, 'deliverable.published_to_client'::text, 'review.changes_requested'::text, 'automation.manual'::text])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_actor uuid := (select auth.uid());
begin
 if not app_private.p13_permission(p_project,v_actor,'integration.manage') then
  raise exception using errcode='42501',message='integration_forbidden'; end if;
 if p_name is null or char_length(btrim(p_name)) not between 1 and 120 or p_key is null or p_events is null
  or cardinality(p_events) not between 1 and 6 or not(p_events <@ array['work.created','work.completed','work.status_changed','deliverable.published_to_client','review.changes_requested','automation.manual']) then
  raise exception using errcode='22023',message='invalid_connection'; end if;
 if p_id is not null then
  select id into v_id from public.integration_connections where id=p_id and project_id=p_project for update;
  if v_id is null then raise exception using errcode='42501',message='integration_forbidden'; end if;
  update public.integration_connections set display_name=btrim(p_name),event_allowlist=p_events,updated_at=now() where id=v_id;
 else
  insert into public.integration_connections(project_id,display_name,event_allowlist,created_by,create_key,consented_by)
  values(p_project,btrim(p_name),p_events,v_actor,p_key,v_actor)
  on conflict(created_by,create_key) do nothing returning id into v_id;
  if v_id is null then
   select id into v_id from public.integration_connections where created_by=v_actor and create_key=p_key and project_id=p_project;
   if v_id is null then raise exception using errcode='22023',message='idempotency_conflict'; end if;
  else
   perform app_private.p13_audit('integration.connection.created',v_actor,'integration_connection',v_id,p_project);
  end if;
 end if;
 return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.phase13_start_ai(p_project uuid, p_actor uuid, p_task text, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.ai_runs%rowtype; v_context jsonb; v_name text; v_role text; v_counts jsonb;
begin
 if not app_private.p13_permission(p_project,p_actor,'ai.use') or not app_private.p13_permission(p_project,p_actor,'project.view') then
  raise exception using errcode='42501',message='ai_forbidden'; end if;
 if not exists(select 1 from public.ai_project_consents where project_id=p_project and enabled) then
  raise exception using errcode='42501',message='consent_required'; end if;
 if p_task is null or p_task not in ('project_summary','draft_work') or p_key is null then
  raise exception using errcode='22023',message='invalid_ai_request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('p13.ai.'||p_actor::text,0));
 select * into v from public.ai_runs where actor_id=p_actor and request_key=p_key;
 if v.id is not null then
  if v.project_id<>p_project or v.task_type<>p_task then raise exception using errcode='22023',message='idempotency_conflict'; end if;
  return jsonb_build_object('id',v.id,'replay',true,'status',v.status);
 end if;
 update public.ai_runs set status='failed',safe_error='provider_unavailable',finished_at=now()
 where actor_id=p_actor and status='running' and started_at<now()-interval '60 seconds';
 if (select count(*) from public.ai_runs where actor_id=p_actor and started_at>now()-interval '1 minute')>=10 then
  raise exception using errcode='54000',message='rate_limited'; end if;
 if (select count(*) from public.ai_runs where actor_id=p_actor and status='running')>=2 then
  raise exception using errcode='54000',message='concurrency_limited'; end if;
 select p.name,am.role_key into v_name,v_role from public.projects p join public.brands b on b.id=p.brand_id
 join public.organizations o on o.id=b.organization_id join public.agency_memberships am on am.agency_id=o.agency_id
 where p.id=p_project and am.user_id=p_actor and am.status='active';
 with visible as materialized (select w.id,left(w.title,160) as title,w.status from public.work_items w
  where w.project_id=p_project and w.archived_at is null and app_private.p13_permission(p_project,p_actor,'work.view')
   and (v_role in ('agency_director','project_manager') or exists(select 1 from public.work_item_assignees a
    where a.work_item_id=w.id and a.user_id=p_actor and a.revoked_at is null))),
 bounded as (select * from visible order by id limit 20)
 select jsonb_build_object('project_name',left(v_name,120),'open_work',(select count(*) from visible where status not in ('done','cancelled')),
  'completed_work',(select count(*) from visible where status='done'),'work_titles',coalesce(jsonb_agg(title),'[]'::jsonb)) into v_context from bounded;
 v_counts:=jsonb_build_object('work_items',jsonb_array_length(v_context->'work_titles'));
 insert into public.ai_runs(project_id,actor_id,request_key,task_type,provider,model,template_key,template_version,context_counts)
 values(p_project,p_actor,p_key,p_task,'local_deterministic','omnia-local-v1',p_task,1,v_counts) returning * into v;
 return jsonb_build_object('id',v.id,'replay',false,'context',v_context,'template_version',1);
end; $function$

CREATE OR REPLACE FUNCTION public.phase13_store_credentials(p_connection uuid, p_actor uuid, p_url text, p_cipher jsonb, p_key uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.integration_connections%rowtype;
begin
 select * into v from public.integration_connections where id=p_connection for update;
 if v.id is null or not app_private.p13_permission(v.project_id,p_actor,'integration.manage') then
  raise exception using errcode='42501',message='integration_forbidden'; end if;
 if p_key is null then raise exception using errcode='22023',message='invalid_connection'; end if;
 if v.last_config_key=p_key then return; end if;
 if p_url is null or char_length(p_url)>2048 or p_cipher is null or jsonb_typeof(p_cipher)<>'object'
  or p_cipher->>'algorithm' is distinct from 'AES-GCM' or coalesce(p_cipher->>'key_version','') !~ '^[1-9][0-9]{0,3}$'
  or not(p_cipher ?& array['iv','ciphertext']) then
  raise exception using errcode='22023',message='invalid_credentials_envelope'; end if;
 insert into app_private.integration_credentials(connection_id,endpoint_url,encrypted_secret) values(v.id,p_url,p_cipher)
 on conflict(connection_id) do update set endpoint_url=excluded.endpoint_url,encrypted_secret=excluded.encrypted_secret,updated_at=now();
 update public.integration_connections set status='active',credentials_version=credentials_version+1,
  consented_by=p_actor,consented_at=now(),updated_at=now(),last_config_key=p_key where id=v.id;
 perform app_private.p13_audit('integration.secret.changed',p_actor,'integration_connection',v.id,v.project_id,
  jsonb_build_object('credentials_version',v.credentials_version+1));
end; $function$

CREATE OR REPLACE FUNCTION public.phase13_test_connection(p_connection uuid, p_actor uuid, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.integration_connections%rowtype; d public.webhook_deliveries%rowtype; v_id uuid;
begin
 select * into c from public.integration_connections where id=p_connection for update;
 if c.id is null or c.status<>'active' or not app_private.p13_permission(c.project_id,p_actor,'integration.manage') then
  raise exception using errcode='42501',message='integration_forbidden'; end if;
 if p_key is null then raise exception using errcode='22023',message='invalid_test'; end if;
 perform pg_advisory_xact_lock(hashtextextended('p13.connection_test.'||p_actor::text,0));
 select * into d from public.webhook_deliveries where requested_by=p_actor and request_key=p_key;
 if d.id is not null then
  if d.connection_id<>c.id then raise exception using errcode='22023',message='idempotency_conflict'; end if;
  return jsonb_build_object('id',d.id,'replay',true,'status',d.status);
 end if;
 if (select count(*) from public.webhook_deliveries where requested_by=p_actor and created_at>now()-interval '1 minute')>=5 then
  raise exception using errcode='54000',message='rate_limited'; end if;
 v_id:=gen_random_uuid();
 insert into public.webhook_deliveries(id,connection_id,project_id,requested_by,request_key,payload,status,attempt)
 values(v_id,c.id,c.project_id,p_actor,p_key,jsonb_build_object('version',1,'event_id',v_id,'type','integration.test','project_id',c.project_id),'attempting',1);
 perform app_private.p13_audit('integration.connection.tested',p_actor,'integration_connection',c.id,c.project_id);
 return jsonb_build_object('id',v_id,'replay',false,'status','attempting');
end; $function$

CREATE OR REPLACE FUNCTION public.phase7_submit_deliverable_version(deliverable_id uuid, notes text, idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare v_actor uuid := (select auth.uid()); v_work_id uuid; v_work public.work_items%rowtype;
  v_deliverable public.deliverables%rowtype; v_old public.deliverable_versions%rowtype;
  v_version uuid; v_round uuid; v_number integer; v_count integer;
  v_correlation uuid := gen_random_uuid();
begin
  if v_actor is null or idempotency_key is null or char_length(btrim(coalesce(notes,''))) not between 1 and 12000 then
    raise exception using errcode='22023',message='invalid_submission_input'; end if;
  select d.work_item_id into v_work_id from public.deliverables d where d.id=deliverable_id;
  select * into v_work from public.work_items where id=v_work_id for update;
  if v_work.id is null then raise exception using errcode='42501',message='deliverable_submit_forbidden'; end if;
  -- This row also serializes configuration changes with the requirement snapshot.
  perform 1 from public.projects p where p.id=v_work.project_id for update;
  select * into v_deliverable from public.deliverables d where d.id=deliverable_id for update;
  if v_deliverable.id is null or v_deliverable.work_item_id<>v_work.id then
    raise exception using errcode='42501',message='deliverable_submit_forbidden'; end if;
  select * into v_old from public.deliverable_versions dv
    where dv.submitted_by=v_actor and dv.submission_key=idempotency_key;
  if v_old.id is not null then
    if v_old.deliverable_id<>deliverable_id or v_old.notes<>btrim(notes) then
      raise exception using errcode='22023',message='idempotency_key_conflict'; end if;
    return v_old.id;
  end if;
  if not app_private.phase7_can_submit(v_work.id,'deliverable.submit') then
    raise exception using errcode='42501',message='deliverable_submit_forbidden'; end if;
  if v_deliverable.archived_at is not null or v_deliverable.status not in ('draft','changes_requested') then
    raise exception using errcode='22023',message='deliverable_not_submittable'; end if;
  if not exists(select 1 from public.review_requirements rr where rr.active
    and rr.project_id=v_work.project_id and rr.deliverable_id is not distinct from deliverable_id)
    and not exists(select 1 from public.review_requirements rr where rr.active
      and rr.project_id=v_work.project_id and rr.deliverable_id is null) then
    raise exception using errcode='22023',message='review_requirements_missing'; end if;
  if exists(select 1 from public.review_requirements rr where rr.active and rr.project_id=v_work.project_id
    and rr.reviewer_id=v_actor and (rr.deliverable_id=deliverable_id or
      (rr.deliverable_id is null and not exists(select 1 from public.review_requirements x
        where x.active and x.deliverable_id=deliverable_id)))) then
    raise exception using errcode='22023',message='submitter_cannot_review_self'; end if;
  if exists(select 1 from public.review_requirements rr where rr.active and rr.project_id=v_work.project_id
    and (rr.deliverable_id=deliverable_id or (rr.deliverable_id is null and not exists(
      select 1 from public.review_requirements x where x.active and x.deliverable_id=deliverable_id)))
    and not app_private.phase7_reviewer_eligible(v_work.project_id,rr.reviewer_id)) then
    raise exception using errcode='22023',message='reviewer_not_eligible'; end if;
  select coalesce(max(dv.version_number),0)+1 into v_number from public.deliverable_versions dv
    where dv.deliverable_id=deliverable_id;
  insert into public.deliverable_versions(deliverable_id,version_number,notes,submitted_by,submission_key)
    values(deliverable_id,v_number,btrim(notes),v_actor,idempotency_key) returning id into v_version;
  insert into public.review_rounds(deliverable_version_id) values(v_version) returning id into v_round;
  insert into public.review_assignments(review_round_id,requirement_id,reviewer_id,requirement_scope)
  select v_round,rr.id,rr.reviewer_id,case when rr.deliverable_id is null then 'project' else 'deliverable' end
  from public.review_requirements rr where rr.active and rr.project_id=v_work.project_id
    and (rr.deliverable_id=deliverable_id or (rr.deliverable_id is null and not exists(
      select 1 from public.review_requirements x where x.active and x.deliverable_id=deliverable_id)));
  get diagnostics v_count = row_count;
  if v_count=0 then raise exception using errcode='22023',message='review_requirements_missing'; end if;
  update public.deliverables set status='in_review' where id=deliverable_id;
  if v_work.status='todo' then update public.work_items set status='in_progress' where id=v_work.id; end if;
  perform app_private.phase7_event(v_work.id,'deliverable.version.submitted',v_actor,'deliverable_version',v_version,
    v_correlation,idempotency_key,jsonb_build_object('deliverable_id',deliverable_id,'version_number',v_number));
  perform app_private.phase7_event(v_work.id,'review.round.opened',v_actor,'review_round',v_round,
    v_correlation,idempotency_key,jsonb_build_object('deliverable_version_id',v_version,'required_count',v_count));
  return v_version;
end; $function$

CREATE OR REPLACE FUNCTION public.publish_billing_document(p_document_id uuid, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target_doc public.billing_documents%rowtype;
  target_organization uuid;
  target_agency uuid;
  publish_event uuid;
begin
  perform app_private.assert_billing_command(p_document_id,'billing.publish',p_idempotency_key);
  if p_idempotency_key is not null then
    select de.resource_id into publish_event
    from public.domain_events as de
    where de.actor_id = actor
      and de.event_type = 'billing.document.published'
      and de.idempotency_key = p_idempotency_key;
    if publish_event is not null then
      if publish_event<>p_document_id then raise exception using errcode='22023',message='idempotency_conflict'; end if;
      return p_document_id; end if;
  end if;

  select * into target_doc from public.billing_documents where id = p_document_id for update;
  if target_doc.id is null then raise exception using errcode = 'P0001', message = 'not_found'; end if;
  if target_doc.status = 'draft' then raise exception using errcode = 'P0001', message = 'cannot_publish_draft'; end if;
  if target_doc.published_to_client then return p_document_id; end if;

  select o.id, o.agency_id into target_organization, target_agency
  from public.organizations o where o.id = target_doc.organization_id;

  if not public.is_internal_actor() then raise exception using errcode = '42501', message = 'forbidden'; end if;
  if target_doc.project_id is not null and not public.project_access_allowed(target_doc.project_id, 'billing.publish') then
    if not public.has_capability('billing.publish', target_agency, target_organization) then
      raise exception using errcode = '42501', message = 'forbidden';
    end if;
  elsif target_doc.project_id is null and not public.has_capability('billing.publish', target_agency, target_organization) then
    raise exception using errcode = '42501', message = 'forbidden';
  end if;

  update public.billing_documents
  set published_to_client = true,
      published_at = now()
  where id = p_document_id;

  perform app_private.emit_event(
    'billing.document.published', actor, 'billing_document', p_document_id,
    target_agency, target_organization, p_document_id, p_idempotency_key, '{}'::jsonb
  );

  return p_document_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_deliverable_to_client(deliverable_id uuid, idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare v_actor uuid:=auth.uid(); v_d public.deliverables%rowtype; v_version uuid;
 v_prior public.client_publications%rowtype; v_publication uuid; v_review uuid; v_count integer;
 v_event uuid; v_correlation uuid:=gen_random_uuid();
begin
 if v_actor is null or idempotency_key is null then
  raise exception using errcode='22023',message='invalid_publication_input'; end if;
 select * into v_prior from public.client_publications cp
  where cp.published_by=v_actor and cp.idempotency_key=idempotency_key;
 if v_prior.id is not null then
  if v_prior.deliverable_id<>deliverable_id then
   raise exception using errcode='22023',message='idempotency_key_conflict'; end if;
  return deliverable_id;
 end if;
 select * into v_d from public.deliverables d where d.id=deliverable_id for update;
 if v_d.id is null or v_d.archived_at is not null or not app_private.project_permission(v_d.project_id,'deliverable.publish') then
  raise exception using errcode='42501',message='deliverable_publish_forbidden'; end if;
 if v_d.status<>'ready_for_client' then
  raise exception using errcode='22023',message='deliverable_not_ready'; end if;
 select dv.id into v_version from public.deliverable_versions dv
 join public.review_rounds rr on rr.deliverable_version_id=dv.id and rr.status='approved'
 where dv.deliverable_id=deliverable_id order by dv.version_number desc limit 1;
 if v_version is null or v_version is distinct from
   (select dv.id from public.deliverable_versions dv where dv.deliverable_id=deliverable_id
    order by dv.version_number desc limit 1) then
  raise exception using errcode='22023',message='latest_version_not_approved'; end if;
 if exists(select 1 from public.client_publications cp where cp.version_id=v_version) then
  raise exception using errcode='22023',message='version_already_published'; end if;
 if exists(select 1 from public.deliverable_files df join public.file_assets fa on fa.id=df.asset_id
   where df.deliverable_version_id=v_version and fa.status<>'ready') then
  raise exception using errcode='22023',message='published_files_unavailable'; end if;
 insert into public.client_publications(deliverable_id,project_id,version_id,published_by,idempotency_key)
  values(deliverable_id,v_d.project_id,v_version,v_actor,idempotency_key) returning id into v_publication;
 insert into public.client_reviews(publication_id) values(v_publication) returning id into v_review;
 insert into public.client_review_assignments(client_review_id,reviewer_id)
 select v_review,pm.user_id from public.project_memberships pm
 join public.projects p on p.id=pm.project_id join public.brands b on b.id=p.brand_id
 join public.client_memberships cm on cm.organization_id=b.organization_id and cm.user_id=pm.user_id
 where pm.project_id=v_d.project_id and pm.member_type='client' and pm.status='active'
  and cm.status='active' and cm.role_key='client_reviewer';
 get diagnostics v_count=row_count;
 if v_count=0 then raise exception using errcode='22023',message='client_reviewers_missing'; end if;
 update public.deliverables set status='published_to_client',publish_key=idempotency_key,
  published_by=v_actor,published_at=now(),published_version_id=v_version where id=deliverable_id;
 v_event:=app_private.phase7_event(v_d.work_item_id,'deliverable.published_to_client',v_actor,
  'deliverable',deliverable_id,v_correlation,idempotency_key,
  jsonb_build_object('publication_id',v_publication,'version_id',v_version));
 insert into public.notifications(recipient_id,domain_event_id,kind,project_id,deliverable_id)
 select pm.user_id,v_event,'deliverable_published',v_d.project_id,deliverable_id
 from public.project_memberships pm where pm.project_id=v_d.project_id
  and pm.member_type='client' and pm.status='active'
  and app_private.client_project_access(v_d.project_id,pm.user_id);
 insert into public.notifications(recipient_id,domain_event_id,kind,project_id,deliverable_id)
 select a.reviewer_id,v_event,'approval_pending',v_d.project_id,deliverable_id
 from public.client_review_assignments a where a.client_review_id=v_review;
 return deliverable_id;
end; $function$

CREATE OR REPLACE FUNCTION public.publish_editorial_available(item_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); target public.editorial_items%rowtype; work_id uuid;
begin
  select ei.work_item_id into work_id from public.editorial_items ei where ei.id=item_id;
  perform 1 from public.work_items wi where wi.id=work_id for update;
  select * into target from public.editorial_items ei where ei.id=item_id for update;
  if actor is null or target.id is null or target.planning_state <> 'planned'
    or not app_private.editorial_permission(target.project_id,'editorial.publish_available')
    or exists(select 1 from public.work_item_assignees wia where wia.work_item_id=work_id and wia.revoked_at is null)
    or exists(select 1 from public.work_items wi where wi.id=work_id and (wi.archived_at is not null or wi.status <> 'todo'))
    or not exists(select 1 from public.editorial_cycles ec where ec.id=target.cycle_id and ec.status='open') then
    raise exception using errcode='42501', message='editorial_publish_forbidden';
  end if;
  update public.editorial_items set planning_state='available' where id=item_id;
  perform app_private.record_editorial_event(target.project_id,'editorial.item.available','editorial_item',item_id,actor,gen_random_uuid(),null,'{}');
  return item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.push_claim_delivery()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_delivery app_private.push_delivery_outbox%rowtype;
begin
 if current_setting('request.jwt.claim.role',true) is distinct from 'service_role'
 and coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'worker_only' using errcode='42501'; end if;
 update app_private.push_delivery_outbox d set status='cancelled',claim_token=null,lease_until=null
 where d.status in ('pending','sending') and not app_private.push_eligible(d.notification_id,d.subscription_id,d.generation);
 update app_private.push_delivery_outbox set status='failed',last_error='retry_exhausted',claim_token=null,lease_until=null
 where status='sending' and lease_until<now() and attempts>=5;
 select * into v_delivery from app_private.push_delivery_outbox
 where (status='pending' and available_at<=now() or status='sending' and lease_until<now())
 and attempts<5 order by created_at,id for update skip locked limit 1;
 if not found then return null; end if;
 update app_private.push_delivery_outbox set status='sending',attempts=attempts+1,
 claim_token=gen_random_uuid(),lease_until=now()+interval '60 seconds'
 where id=v_delivery.id returning * into v_delivery;
 return jsonb_build_object('id',v_delivery.id,'token',v_delivery.claim_token,'attempt',v_delivery.attempts);
end; $function$

CREATE OR REPLACE FUNCTION public.push_delivery_material(p_delivery uuid, p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_delivery app_private.push_delivery_outbox%rowtype; v_subscription app_private.push_subscriptions%rowtype;
begin
 if coalesce(auth.jwt()->>'role',current_setting('request.jwt.claim.role',true),'')<>'service_role' then
  raise exception 'worker_only' using errcode='42501'; end if;
 select * into v_delivery from app_private.push_delivery_outbox where id=p_delivery and status='sending'
 and claim_token=p_token and lease_until>now();
 if not found or not app_private.push_eligible(v_delivery.notification_id,v_delivery.subscription_id,v_delivery.generation) then
  raise exception 'stale_claim' using errcode='42501'; end if;
 select * into v_subscription from app_private.push_subscriptions where id=v_delivery.subscription_id;
 return jsonb_build_object('subscription',jsonb_build_object('endpoint',v_subscription.endpoint,
  'keys',jsonb_build_object('p256dh',v_subscription.p256dh,'auth',v_subscription.auth_key)),
  'payload',jsonb_build_object('notification_id',v_delivery.notification_id,'surface',v_subscription.surface,
   'device_token',v_subscription.device_token,
   'endpoint_hash',encode(extensions.digest(v_subscription.endpoint,'sha256'),'hex')));
end; $function$

CREATE OR REPLACE FUNCTION public.push_finish_delivery(p_delivery uuid, p_token uuid, p_status integer, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_delivery app_private.push_delivery_outbox%rowtype; v_error text; v_retry boolean;
begin
 if coalesce(auth.jwt()->>'role',current_setting('request.jwt.claim.role',true),'')<>'service_role' then
  raise exception 'worker_only' using errcode='42501'; end if;
 select * into v_delivery from app_private.push_delivery_outbox where id=p_delivery and status='sending'
 and claim_token=p_token and lease_until>now() for update;
 if not found then return false; end if;
 if not app_private.push_eligible(v_delivery.notification_id,v_delivery.subscription_id,v_delivery.generation) then
  update app_private.push_delivery_outbox set status='cancelled',lease_until=null,claim_token=null where id=p_delivery;
  return false;
 end if;
 if p_status between 200 and 299 then
  update app_private.push_delivery_outbox set status='delivered',delivered_at=now(),last_error=null,lease_until=null,claim_token=null where id=p_delivery;
  update app_private.push_subscriptions set last_success_at=now(),last_error=null where id=v_delivery.subscription_id;
  return true;
 end if;
 v_error:=case when p_status in (404,410) then 'gone' when p_status=429 then 'rate_limited'
  when p_status>=500 then 'unavailable' when p_status is null and p_error='timeout' then 'timeout' else 'rejected' end;
 v_retry:=v_error in ('rate_limited','unavailable','timeout') and v_delivery.attempts<5;
 update app_private.push_delivery_outbox set status=case when v_retry then 'pending' else 'failed' end,
  last_error=case when v_error in ('rate_limited','unavailable','timeout') and not v_retry then 'retry_exhausted' else v_error end,
  available_at=now()+make_interval(secs=>least(3600,30*power(2,v_delivery.attempts-1)::integer)),lease_until=null,claim_token=null where id=p_delivery;
 update app_private.push_subscriptions set active=case when v_error='gone' then false else active end,
  last_error=v_error,updated_at=now() where id=v_delivery.subscription_id;
 if v_error='gone' then
  update app_private.push_delivery_outbox set status='cancelled',lease_until=null,claim_token=null
  where subscription_id=v_delivery.subscription_id and status in ('pending','sending');
 end if;
 return true;
end; $function$

CREATE OR REPLACE FUNCTION public.record_client_decision(assignment_id uuid, decision text, reason text, idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare v_actor uuid:=auth.uid(); v_d public.deliverables%rowtype; v_cp public.client_publications%rowtype;
 v_review public.client_reviews%rowtype; v_a public.client_review_assignments%rowtype;
 v_prior public.client_review_decisions%rowtype; v_id uuid; v_event uuid; v_type text;
begin
 if v_actor is null or idempotency_key is null or decision not in ('approve','request_changes')
   or (decision='request_changes' and char_length(btrim(coalesce(reason,''))) not between 1 and 4000)
   or (reason is not null and char_length(reason)>4000) then
  raise exception using errcode='22023',message='invalid_client_decision'; end if;
 select d.* into v_d from public.client_review_assignments a
 join public.client_reviews cr on cr.id=a.client_review_id
 join public.client_publications cp on cp.id=cr.publication_id
 join public.deliverables d on d.id=cp.deliverable_id where a.id=assignment_id for update of d;
 if v_d.id is null then raise exception using errcode='42501',message='client_decision_forbidden'; end if;
 select cr.* into v_review from public.client_review_assignments a
  join public.client_reviews cr on cr.id=a.client_review_id where a.id=assignment_id for update of cr;
 select * into v_a from public.client_review_assignments a where a.id=assignment_id for update;
 select cp.* into v_cp from public.client_publications cp where cp.id=v_review.publication_id;
 if v_a.reviewer_id<>v_actor or not app_private.client_reviewer_access(v_cp.project_id,v_actor) then
  raise exception using errcode='42501',message='client_decision_forbidden'; end if;
 select * into v_prior from public.client_review_decisions cd where cd.reviewer_id=v_actor
  and cd.idempotency_key=idempotency_key;
 if v_prior.id is not null then
  if v_prior.assignment_id<>assignment_id or v_prior.decision<>decision or v_prior.reason is distinct from nullif(btrim(reason),'') then
   raise exception using errcode='22023',message='idempotency_key_conflict'; end if;
  return v_prior.id;
 end if;
 if v_d.status<>'published_to_client' or v_d.published_version_id<>v_cp.version_id
   or v_review.status<>'pending' or v_a.status<>'pending' then
  raise exception using errcode='22023',message='client_review_closed'; end if;
 insert into public.client_review_decisions(assignment_id,reviewer_id,decision,reason,idempotency_key)
  values(assignment_id,v_actor,decision,nullif(btrim(reason),''),idempotency_key) returning id into v_id;
 update public.client_review_assignments set status=case when decision='approve' then 'approved' else 'changes_requested' end,
  resolved_at=now() where id=assignment_id;
 v_type:=case when decision='approve' then 'client.review.approved' else 'client.review.changes_requested' end;
 v_event:=app_private.phase7_event(v_d.work_item_id,v_type,v_actor,'client_review_decision',v_id,
  gen_random_uuid(),idempotency_key,jsonb_build_object('deliverable_id',v_d.id,'version_id',v_cp.version_id));
 if decision='request_changes' then
  update public.client_reviews set status='changes_requested',closed_at=now() where id=v_review.id;
  update public.deliverables set status='changes_requested' where id=v_d.id;
  update public.work_items set status='in_progress',completed_at=null where id=v_d.work_item_id;
 elsif not exists(select 1 from public.client_review_assignments a where a.client_review_id=v_review.id and a.status='pending') then
  update public.client_reviews set status='approved',closed_at=now() where id=v_review.id;
  update public.deliverables set status='client_approved' where id=v_d.id;
 end if;
 insert into public.notifications(recipient_id,domain_event_id,kind,project_id,deliverable_id)
 select distinct pm.user_id,v_event,
  case when decision='approve' then 'client_approved' else 'client_changes_requested' end,
  v_d.project_id,v_d.id from public.project_memberships pm
 where pm.project_id=v_d.project_id and pm.member_type='internal' and pm.status='active'
  and (decision='request_changes' or not exists(select 1 from public.client_review_assignments pending
   where pending.client_review_id=v_review.id and pending.status='pending'));
 return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.record_payment(p_document_id uuid, p_amount numeric, p_method payment_method, p_received_at timestamp with time zone, p_reference text, p_notes text, p_file_asset_id uuid, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target_doc public.billing_documents%rowtype;
  target_organization uuid;
  target_agency uuid;
  payment_id uuid;
  paid_amount numeric(14,2);
  new_status public.billing_document_status;
begin
  perform app_private.assert_billing_command(p_document_id,'billing.record_payment',p_idempotency_key);
  if p_idempotency_key is not null then
    select de.resource_id into payment_id
    from public.domain_events as de
    where de.actor_id = actor
      and de.event_type = 'billing.payment.recorded'
      and de.idempotency_key = p_idempotency_key;
    if payment_id is not null then
      if not exists(select 1 from public.payment_records where id=payment_id and billing_document_id=p_document_id
       and amount=p_amount and method=p_method and received_at=p_received_at and reference is not distinct from p_reference
       and notes is not distinct from p_notes and file_asset_id is not distinct from p_file_asset_id)
      then raise exception using errcode='22023',message='idempotency_conflict'; end if;
      return payment_id; end if;
  end if;

  select * into target_doc from public.billing_documents where id = p_document_id for update;
  if target_doc.id is null then raise exception using errcode = 'P0001', message = 'not_found'; end if;
  if target_doc.status not in ('issued', 'partially_paid') then raise exception using errcode = 'P0001', message = 'invalid_document_status'; end if;

  select o.id, o.agency_id into target_organization, target_agency
  from public.organizations o where o.id = target_doc.organization_id;

  if not public.is_internal_actor() then raise exception using errcode = '42501', message = 'forbidden'; end if;
  if target_doc.project_id is not null and not public.project_access_allowed(target_doc.project_id, 'billing.record_payment') then
    if not public.has_capability('billing.record_payment', target_agency, target_organization) then
      raise exception using errcode = '42501', message = 'forbidden';
    end if;
  elsif target_doc.project_id is null and not public.has_capability('billing.record_payment', target_agency, target_organization) then
    raise exception using errcode = '42501', message = 'forbidden';
  end if;

  if p_amount is null or p_amount::text in ('NaN','Infinity','-Infinity') or p_amount<>round(p_amount,2) or p_amount <= 0 then raise exception using errcode = '23514', message = 'invalid_amount'; end if;

  if p_file_asset_id is not null and not exists(select 1 from public.file_assets f
    join public.projects p on p.id=f.project_id join public.brands b on b.id=p.brand_id where f.id=p_file_asset_id
    and f.status='ready' and b.organization_id=target_doc.organization_id
    and (target_doc.project_id is null or f.project_id=target_doc.project_id) and public.project_access_allowed(f.project_id,'file.view'))
    then raise exception using errcode='42501',message='forbidden'; end if;
  -- Overpayment validation
  select coalesce(sum(amount), 0) into paid_amount
  from public.payment_records
  where billing_document_id = p_document_id and voided_at is null;

  if (paid_amount + p_amount) > target_doc.total_amount then
    raise exception using errcode = '23514', message = 'overpayment_rejected';
  end if;

  insert into public.payment_records (
    billing_document_id, amount, currency, received_at, method, reference, notes, file_asset_id, recorded_by
  ) values (
    p_document_id, p_amount, target_doc.currency, p_received_at, p_method, p_reference, p_notes, p_file_asset_id, actor
  ) returning id into payment_id;

  if (paid_amount + p_amount) >= target_doc.total_amount then
    new_status := 'paid';
  else
    new_status := 'partially_paid';
  end if;

  update public.billing_documents
  set status = new_status
  where id = p_document_id;

  perform app_private.emit_event(
    'billing.payment.recorded', actor, 'payment_record', payment_id,
    target_agency, target_organization, p_document_id, p_idempotency_key, '{}'::jsonb
  );

  return payment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_review_decision(review_assignment_id uuid, decision text, reason text, idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare v_actor uuid := (select auth.uid()); v_work_id uuid; v_project uuid;
  v_deliverable public.deliverables%rowtype; v_round public.review_rounds%rowtype;
  v_assignment public.review_assignments%rowtype; v_prior public.review_decisions%rowtype;
  v_version public.deliverable_versions%rowtype; v_id uuid; v_correlation uuid := gen_random_uuid();
begin
  if v_actor is null or idempotency_key is null or decision not in ('approve','request_changes')
    or (decision='request_changes' and char_length(btrim(coalesce(reason,''))) not between 1 and 4000)
    or (reason is not null and char_length(reason)>4000) then
    raise exception using errcode='22023',message='invalid_review_decision'; end if;
  select d.work_item_id into v_work_id from public.review_assignments a
  join public.review_rounds r on r.id=a.review_round_id
  join public.deliverable_versions dv on dv.id=r.deliverable_version_id
  join public.deliverables d on d.id=dv.deliverable_id where a.id=review_assignment_id;
  perform 1 from public.work_items wi where wi.id=v_work_id for update;
  select d.* into v_deliverable from public.deliverables d where d.work_item_id=v_work_id for update;
  select r.* into v_round from public.review_assignments a
    join public.review_rounds r on r.id=a.review_round_id where a.id=review_assignment_id for update of r;
  select * into v_assignment from public.review_assignments a where a.id=review_assignment_id for update;
  select * into v_version from public.deliverable_versions dv where dv.id=v_round.deliverable_version_id;
  v_project := v_deliverable.project_id;
  if v_assignment.id is null or v_assignment.reviewer_id<>v_actor
    or not app_private.phase7_reviewer_eligible(v_project,v_actor)
    or not app_private.project_permission(v_project,'review.decide')
    or v_version.submitted_by=v_actor then
    raise exception using errcode='42501',message='review_decision_forbidden'; end if;
  select * into v_prior from public.review_decisions rd where rd.review_assignment_id=review_assignment_id;
  if v_prior.id is not null then
    if v_prior.idempotency_key=idempotency_key and v_prior.decision=decision
      and coalesce(v_prior.reason,'')=coalesce(nullif(btrim(reason),''),'') then return v_prior.id; end if;
    raise exception using errcode='22023',message='review_already_decided';
  end if;
  if v_round.status<>'pending' or v_assignment.status<>'pending' or v_deliverable.status<>'in_review' then
    raise exception using errcode='22023',message='review_round_closed'; end if;
  insert into public.review_decisions(review_assignment_id,reviewer_id,decision,reason,idempotency_key)
  values(review_assignment_id,v_actor,decision,nullif(btrim(reason),''),idempotency_key) returning id into v_id;
  update public.review_assignments set status=case when decision='approve' then 'approved' else 'changes_requested' end,
    resolved_at=now() where id=review_assignment_id;
  perform app_private.phase7_event(v_work_id,'review.decision.recorded',v_actor,'review_decision',v_id,
    v_correlation,idempotency_key,jsonb_build_object('review_round_id',v_round.id,'review_assignment_id',review_assignment_id,
      'decision',decision,'deliverable_version_id',v_version.id));
  perform app_private.phase7_resolve_round(v_round.id,v_work_id,v_deliverable.id,v_actor,idempotency_key,v_correlation);
  return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.register_push_subscription(p_subscription jsonb, p_surface text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_session uuid:=app_private.push_session(); v_user uuid:=auth.uid(); v_id uuid;
 v_existing app_private.push_subscriptions%rowtype; v_endpoint text:=p_subscription->>'endpoint';
begin
 if jsonb_typeof(p_subscription)<>'object' or jsonb_typeof(p_subscription->'keys')<>'object'
  or not (p_subscription ?& array['endpoint','keys'])
  or (p_subscription - array['endpoint','keys','expirationTime','device_token'])<>'{}'::jsonb
  or not coalesce(p_subscription->>'device_token' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',false)
  or ((p_subscription->'keys') - array['p256dh','auth'])<>'{}'::jsonb
  or not coalesce(app_private.valid_push_endpoint(v_endpoint),false)
  or not coalesce(p_subscription->'keys'->>'p256dh' ~ '^[A-Za-z0-9_-]{87}$',false)
  or not coalesce(p_subscription->'keys'->>'auth' ~ '^[A-Za-z0-9_-]{22}$',false)
  or p_surface not in ('app','portal') or p_surface is null then
  raise exception 'invalid_subscription' using errcode='22023';
 end if;
 if (p_surface='app' and not exists(select 1 from public.agency_memberships where user_id=v_user and status='active'))
  or (p_surface='portal' and not exists(select 1 from public.client_memberships where user_id=v_user and status='active')) then
  raise exception 'surface_forbidden' using errcode='42501';
 end if;
 -- Endpoint lock serializes registration/reassignment across users/devices.
 perform pg_advisory_xact_lock(hashtextextended(v_endpoint,14));
 select * into v_existing from app_private.push_subscriptions where endpoint=v_endpoint for update;
 if found and v_existing.active and v_existing.user_id<>v_user then
  raise exception 'endpoint_owned' using errcode='42501';
 end if;
 if v_existing.id is not null and (v_existing.user_id<>v_user or v_existing.session_id<>v_session
   or not v_existing.active or v_existing.p256dh<>p_subscription->'keys'->>'p256dh'
   or v_existing.auth_key<>p_subscription->'keys'->>'auth' or v_existing.device_token<>(p_subscription->>'device_token')::uuid) then
  update app_private.push_delivery_outbox set status='cancelled',claim_token=null,lease_until=null
   where subscription_id=v_existing.id and status in ('pending','sending');
 end if;
 insert into app_private.push_subscriptions(user_id,session_id,endpoint,p256dh,auth_key,surface,device_token)
 values(v_user,v_session,v_endpoint,p_subscription->'keys'->>'p256dh',p_subscription->'keys'->>'auth',p_surface,(p_subscription->>'device_token')::uuid)
 on conflict(endpoint) do update set user_id=excluded.user_id,session_id=excluded.session_id,
  p256dh=excluded.p256dh,auth_key=excluded.auth_key,surface=excluded.surface,device_token=excluded.device_token,active=true,updated_at=now(),last_error=null,
  generation=app_private.push_subscriptions.generation + case when v_existing.user_id<>v_user
   or v_existing.session_id<>v_session or not v_existing.active or v_existing.p256dh<>excluded.p256dh
   or v_existing.auth_key<>excluded.auth_key or v_existing.device_token<>excluded.device_token then 1 else 0 end
 returning id into v_id;
 insert into public.notification_preferences(user_id,push_enabled) values(v_user,true)
 on conflict(user_id) do update set push_enabled=true,updated_at=now();
 return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.remove_channel_member(p_channel uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_c public.channels%rowtype; v_id uuid;
begin
 select * into v_c from public.channels where id=p_channel and archived_at is null for update;
 if v_c.id is null or not app_private.can_manage_channel(p_channel) or v_c.kind='organization'
  and exists(select 1 from public.client_memberships where organization_id=v_c.organization_id
   and user_id=p_user and status='active') then
  raise exception using errcode='42501',message='channel_member_forbidden'; end if;
 update public.channel_memberships set status='removed',removed_at=coalesce(removed_at,now())
 where channel_id=p_channel and user_id=p_user and status='active' returning id into v_id;
 if v_id is not null then
  perform app_private.emit_event('channel.member.removed',auth.uid(),'channel_membership',v_id,null,v_c.organization_id,
   gen_random_uuid(),null,jsonb_build_object('channel_id',p_channel,'user_id',p_user));
 end if;
end; $function$

CREATE OR REPLACE FUNCTION public.request_file_permanent_delete(asset_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_asset public.file_assets%rowtype;
begin
 select * into v_asset from public.file_assets where id=asset_id for update;
 if auth.uid() is null or v_asset.id is null
   or not app_private.file_director_permission(v_asset.project_id)
   or exists(select 1 from public.deliverable_files df where df.asset_id=v_asset.id)
   or exists(select 1 from public.content_asset_links cal where cal.asset_id=v_asset.id)
 then raise exception using errcode='42501',message='file_delete_forbidden'; end if;
 if v_asset.status not in ('ready','archived','deleting')
 then raise exception using errcode='22023',message='file_delete_invalid_state'; end if;
 if v_asset.status<>'deleting' then
  update public.file_assets set status='deleting' where id=asset_id;
  perform app_private.file_event(asset_id,'file.delete.requested');
 end if;
 return asset_id;
end; $function$

CREATE OR REPLACE FUNCTION public.send_message(p_channel uuid, p_body text, p_client_message_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_c public.channels%rowtype; v_m public.messages%rowtype;
 v_member public.channel_memberships%rowtype; v_event uuid; v_rec record;
 v_agency uuid;
begin
 if v_actor is null or p_client_message_id is null or p_body is null
  or char_length(btrim(p_body)) not between 1 and 4000 then
  raise exception using errcode='22023',message='invalid_message'; end if;
 perform pg_advisory_xact_lock(hashtextextended(v_actor::text||p_client_message_id::text,0));
 select * into v_m from public.messages where author_user_id=v_actor and client_message_id=p_client_message_id;
 if v_m.id is not null then
  if v_m.channel_id<>p_channel or v_m.body<>btrim(p_body) then
   raise exception using errcode='22023',message='idempotency_key_conflict'; end if;
  return v_m.id;
 end if;
 select * into v_c from public.channels where id=p_channel and archived_at is null for share;
 select * into v_member from public.channel_memberships where channel_id=p_channel and user_id=v_actor for share;
 if v_c.id is null or v_member.id is null or v_member.status<>'active' then
  raise exception using errcode='42501',message='message_send_forbidden'; end if;
 if v_member.member_kind='client' then
  perform 1 from public.client_memberships where user_id=v_actor and organization_id=v_c.organization_id
   and status='active' for share;
  if not found then raise exception using errcode='42501',message='message_send_forbidden'; end if;
  if v_c.kind='project' then
   perform 1 from public.project_memberships where project_id=v_c.project_id and user_id=v_actor
    and member_type='client' and status='active' for share;
   if not found then raise exception using errcode='42501',message='message_send_forbidden'; end if;
  end if;
 else
  perform 1 from public.agency_memberships am join public.organizations o on o.agency_id=am.agency_id
   where o.id=v_c.organization_id and am.user_id=v_actor and am.status='active' for share of am;
  if not found then raise exception using errcode='42501',message='message_send_forbidden'; end if;
  if v_c.kind='project' then
   perform 1 from public.project_memberships where project_id=v_c.project_id and user_id=v_actor
    and member_type='internal' and status='active' for share;
   if not found and not exists(select 1 from public.agency_memberships am
    join public.organizations o on o.agency_id=am.agency_id where o.id=v_c.organization_id
     and am.user_id=v_actor and am.status='active' and am.role_key='agency_director') then
    raise exception using errcode='42501',message='message_send_forbidden'; end if;
  end if;
 end if;
 if not app_private.channel_access(p_channel,v_actor) then
  raise exception using errcode='42501',message='message_send_forbidden'; end if;
 insert into public.messages(channel_id,author_user_id,client_message_id,body)
 values(p_channel,v_actor,p_client_message_id,btrim(p_body)) returning * into v_m;
 select o.agency_id into v_agency from public.organizations o where o.id=v_c.organization_id;
 v_event:=app_private.emit_event('message.sent',v_actor,'message',v_m.id,v_agency,
  v_c.organization_id,p_client_message_id,p_client_message_id,jsonb_build_object('channel_id',p_channel));
 for v_rec in select m.user_id from public.channel_memberships m
  where m.channel_id=p_channel and m.status='active' and m.user_id<>v_actor
   and app_private.channel_access(p_channel,m.user_id)
   and coalesce((select np.messages from public.notification_preferences np where np.user_id=m.user_id),true)
 loop
  insert into public.notifications(recipient_id,domain_event_id,kind,project_id,channel_id,message_id)
  values(v_rec.user_id,v_event,'message_received',v_c.project_id,p_channel,v_m.id)
  on conflict(recipient_id,domain_event_id,kind) do nothing;
 end loop;
 return v_m.id;
end; $function$

CREATE OR REPLACE FUNCTION public.set_project_report_publication(p_report uuid, p_publish boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare report public.project_reports%rowtype;
begin
 select * into report from public.project_reports where id=p_report for update;
 if report.id is null or p_publish is null or not app_private.project_permission(report.project_id,'report.publish') then
  raise exception using errcode='42501',message='report_publish_forbidden'; end if;
 if (report.published_at is not null)=p_publish then return p_report; end if;
 update public.project_reports set published_at=case when p_publish then now() end,
 published_by=case when p_publish then auth.uid() end where id=p_report;
 perform app_private.record_editorial_event(report.project_id,case when p_publish then 'report.published' else 'report.withdrawn' end,
  'project_report',p_report,auth.uid(),gen_random_uuid(),null,jsonb_build_object('report_id',p_report));
 return p_report;
end; $function$

CREATE OR REPLACE FUNCTION public.submit_deliverable_version(deliverable_id uuid, notes text, idempotency_key uuid, asset_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_project uuid; v_version uuid; v_existing uuid; v_count integer; v_distinct integer;
begin
 if auth.uid() is null or asset_ids is null or cardinality(asset_ids)>20 or array_position(asset_ids,null) is not null
 then raise exception using errcode='22023',message='invalid_submission_assets'; end if;
 select d.project_id into v_project from public.deliverables d where d.id=deliverable_id;
 if v_project is null or not app_private.project_permission(v_project,'file.link')
 then raise exception using errcode='42501',message='file_link_forbidden'; end if;
 -- Serialize retries before comparing their file sets, including concurrent empty sets.
 perform 1 from public.work_items wi join public.deliverables d on d.work_item_id=wi.id
  where d.id=deliverable_id for update of wi;
 select count(*),count(distinct x.id) into v_count,v_distinct from unnest(asset_ids) x(id);
 if v_count<>v_distinct then raise exception using errcode='22023',message='duplicate_submission_asset'; end if;
 select dv.id into v_existing from public.deliverable_versions dv
 where dv.submitted_by=auth.uid() and dv.submission_key=idempotency_key;
 if v_existing is not null and exists(
  select id from unnest(asset_ids) x(id)
  except select df.asset_id from public.deliverable_files df where df.deliverable_version_id=v_existing
  union all
  (select df.asset_id from public.deliverable_files df where df.deliverable_version_id=v_existing
   except select id from unnest(asset_ids) x(id))
 ) then raise exception using errcode='22023',message='idempotency_key_conflict'; end if;
 -- Existing versions retain their original file set even if an asset was archived later.
 if v_existing is not null then
  return public.phase7_submit_deliverable_version(deliverable_id,notes,idempotency_key);
 end if;
 -- Share locks serialize new submissions with archive and delete commands.
 perform 1 from public.file_assets fa where fa.id=any(asset_ids) for share;
 if (select count(*) from public.file_assets fa where fa.id=any(asset_ids)
    and fa.project_id=v_project and fa.status='ready')<>v_count
 then raise exception using errcode='42501',message='submission_asset_forbidden'; end if;
 v_version:=public.phase7_submit_deliverable_version(deliverable_id,notes,idempotency_key);
 insert into public.deliverable_files(deliverable_version_id,asset_id,ordinal)
  select v_version,x.id,x.ordinality::integer from unnest(asset_ids) with ordinality x(id,ordinality);
 if v_count>0 then perform app_private.file_event(asset_ids[1],'deliverable.version.assets_attached'); end if;
 return v_version;
end; $function$

CREATE OR REPLACE FUNCTION public.update_content_template(template_id uuid, name text, default_channel text, default_format text, default_brief text, archive boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); target public.content_templates%rowtype;
begin
  select * into target from public.content_templates where id = template_id for update;
  if actor is null or target.id is null or target.archived_at is not null
    or not app_private.editorial_permission(target.project_id, 'editorial.plan')
    or (archive and not app_private.editorial_permission(target.project_id, 'editorial.archive')) then
    raise exception using errcode = '42501', message = 'editorial_template_forbidden';
  end if;
  update public.content_templates set name=btrim(update_content_template.name),
    default_channel=update_content_template.default_channel, default_format=update_content_template.default_format,
    default_brief=nullif(btrim(update_content_template.default_brief),''),
    archived_at=case when archive then now() else null end where id=template_id;
  perform app_private.record_editorial_event(target.project_id,
    case when archive then 'editorial.template.archived' else 'editorial.template.updated' end,
    'content_template',template_id,actor,gen_random_uuid(),null,'{}');
  return template_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_editorial_cycle(cycle_id uuid, name text, start_date date, end_date date, status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); target public.editorial_cycles%rowtype;
begin
  select * into target from public.editorial_cycles where id=cycle_id for update;
  if actor is null or target.id is null or target.status='archived'
    or not app_private.editorial_permission(target.project_id, 'editorial.plan')
    or (status='archived' and not app_private.editorial_permission(target.project_id, 'editorial.archive')) then
    raise exception using errcode='42501', message='editorial_cycle_forbidden';
  end if;
  if status not in ('open','closed','archived') or (target.status='closed' and status='open') then
    raise exception using errcode='22023', message='invalid_cycle_transition';
  end if;
  if exists (select 1 from public.editorial_items ei where ei.cycle_id=update_editorial_cycle.cycle_id and ei.archived_at is null
    and (ei.scheduled_date < update_editorial_cycle.start_date or ei.scheduled_date > update_editorial_cycle.end_date)) then
    raise exception using errcode='22023', message='cycle_dates_exclude_items';
  end if;
  if status='archived' and exists (
    select 1 from public.editorial_items ei where ei.cycle_id=update_editorial_cycle.cycle_id and ei.archived_at is null
  ) then
    raise exception using errcode='22023', message='cycle_has_active_items';
  end if;
  update public.editorial_cycles set name=btrim(update_editorial_cycle.name),
    start_date=update_editorial_cycle.start_date,end_date=update_editorial_cycle.end_date,
    status=update_editorial_cycle.status,
    archived_at=case when update_editorial_cycle.status='archived' then now() else null end where id=update_editorial_cycle.cycle_id;
  perform app_private.record_editorial_event(target.project_id,
    case when status='archived' then 'editorial.cycle.archived' else 'editorial.cycle.updated' end,
    'editorial_cycle',cycle_id,actor,gen_random_uuid(),null,'{}');
  return cycle_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_editorial_item(item_id uuid, title text, brief text, scheduled_date date, scheduled_time time without time zone, channel text, format text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := (select auth.uid()); target public.editorial_items%rowtype;
  work_id uuid;
begin
  select ei.work_item_id into work_id from public.editorial_items ei where ei.id=item_id;
  perform 1 from public.work_items wi where wi.id=work_id for update;
  select * into target from public.editorial_items where id=item_id for update;
  if actor is null or target.id is null or target.planning_state not in ('planned','available')
    or not app_private.editorial_permission(target.project_id,'editorial.update') then
    raise exception using errcode='42501', message='editorial_update_forbidden';
  end if;
  if not exists (select 1 from public.editorial_cycles ec where ec.id=target.cycle_id
    and scheduled_date between ec.start_date and ec.end_date and ec.status='open') then
    raise exception using errcode='22023', message='editorial_cycle_date_invalid';
  end if;
  update public.editorial_items set title=btrim(update_editorial_item.title),brief=nullif(btrim(update_editorial_item.brief),''),
    scheduled_date=update_editorial_item.scheduled_date,scheduled_time=update_editorial_item.scheduled_time,
    channel=update_editorial_item.channel,format=update_editorial_item.format where id=item_id;
  update public.work_items set title=btrim(update_editorial_item.title),description=nullif(btrim(update_editorial_item.brief),'')
    where id=target.work_item_id;
  perform app_private.record_editorial_event(target.project_id,'editorial.item.updated','editorial_item',item_id,actor,gen_random_uuid(),null,'{}');
  return item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_personal_work_item(personal_item_id uuid, item_type text, title text, description text, status text, priority text, due_local timestamp without time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target public.personal_work_items%rowtype;
begin
  select * into target
  from public.personal_work_items where id = personal_item_id for update;
  if actor is null or target.id is null or target.user_id <> actor
    or not app_private.is_internal_actor()
    or not public.has_capability('personal_work.manage', null, null) then
    raise exception using errcode = '42501', message = 'personal_work_update_forbidden';
  end if;
  if item_type not in ('todo', 'note', 'reminder')
    or status not in ('open', 'done')
    or priority not in ('low', 'normal', 'high', 'urgent')
    or char_length(btrim(title)) not between 1 and 240 then
    raise exception using errcode = '22023', message = 'invalid_personal_work_input';
  end if;

  update public.personal_work_items
  set item_type = update_personal_work_item.item_type,
      title = btrim(update_personal_work_item.title),
      description = nullif(btrim(update_personal_work_item.description), ''),
      status = update_personal_work_item.status,
      priority = update_personal_work_item.priority,
      due_at = case when due_local is null then null
        else due_local at time zone 'America/Mexico_City' end,
      completed_at = case when update_personal_work_item.status = 'done'
        then coalesce(target.completed_at, now()) else null end,
      archived_at = null
  where id = target.id;
  return target.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.void_payment(p_payment_id uuid, p_reason text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
  target_payment public.payment_records%rowtype;
  target_doc public.billing_documents%rowtype;
  target_organization uuid;
  target_agency uuid;
  void_event uuid;
  paid_amount numeric(14,2);
  new_status public.billing_document_status;
begin
  perform app_private.assert_billing_command((select billing_document_id from public.payment_records where id=p_payment_id),'billing.void_payment',p_idempotency_key);
  if p_idempotency_key is not null then
    select de.resource_id into void_event
    from public.domain_events as de
    where de.actor_id = actor
      and de.event_type = 'billing.payment.voided'
      and de.idempotency_key = p_idempotency_key;
    if void_event is not null then
      if void_event<>p_payment_id then raise exception using errcode='22023',message='idempotency_conflict'; end if;
      return p_payment_id; end if;
  end if;

  perform 1 from public.billing_documents where id=(select billing_document_id from public.payment_records where id=p_payment_id) for update;
  select * into target_payment from public.payment_records where id = p_payment_id for update;
  if target_payment.id is null then raise exception using errcode = 'P0001', message = 'not_found'; end if;
  if target_payment.voided_at is not null then return p_payment_id; end if;

  select * into target_doc from public.billing_documents where id = target_payment.billing_document_id for update;
  select o.id, o.agency_id into target_organization, target_agency
  from public.organizations o where o.id = target_doc.organization_id;

  if not public.is_internal_actor() then raise exception using errcode = '42501', message = 'forbidden'; end if;
  if target_doc.project_id is not null and not public.project_access_allowed(target_doc.project_id, 'billing.void_payment') then
    if not public.has_capability('billing.void_payment', target_agency, target_organization) then
      raise exception using errcode = '42501', message = 'forbidden';
    end if;
  elsif target_doc.project_id is null and not public.has_capability('billing.void_payment', target_agency, target_organization) then
    raise exception using errcode = '42501', message = 'forbidden';
  end if;

  if btrim(coalesce(p_reason, '')) = '' then raise exception using errcode = '23514', message = 'reason_required'; end if;

  update public.payment_records
  set voided_at = now(),
      void_reason = p_reason,
      voided_by = actor
  where id = p_payment_id;

  select coalesce(sum(amount), 0) into paid_amount
  from public.payment_records
  where billing_document_id = target_doc.id and voided_at is null;

  if paid_amount >= target_doc.total_amount then
    new_status := 'paid';
  elsif paid_amount > 0 then
    new_status := 'partially_paid';
  else
    new_status := 'issued';
  end if;

  update public.billing_documents
  set status = new_status
  where id = target_doc.id;

  perform app_private.emit_event(
    'billing.payment.voided', actor, 'payment_record', p_payment_id,
    target_agency, target_organization, target_doc.id, p_idempotency_key, jsonb_build_object('reason', p_reason)
  );

  return p_payment_id;
end;
$function$
